function safeLoadBlock(label, loader){
  return Promise.resolve().then(loader).catch(function(e){
    if(v242IsFirestoreInternalError(e)){
      console.error("[V254] Estado interno de Firestore detectado en "+label,e);
      v242ScheduleFirestoreRecovery(e);
      throw e;
    }
    console.warn("Consulta no disponible:",label,e);
    state.loadWarnings=state.loadWarnings||[];
    var msg=(e&&e.message)?e.message:String(e||"Error desconocido");
    var code=String(e&&e.code||"").toLowerCase();
    var prefix=code.indexOf("permission-denied")>=0
      ?"Permiso denegado"
      :(navigator.onLine===false?"Sin conexión":"Consulta fallida");
    state.loadWarnings.push(label+": "+prefix+" · "+msg);
    return [];
  });
}

function v242LegacyLoadData(){
  if(!firebaseReady || !db || !state.user){return Promise.resolve();}
  state.loadWarnings=[];
  var cutOnly=isCutRoleRuntimeUser() || normalizeRole(state.user&&state.user.role)==="auxiliar_corte";
  return Promise.all([
    safeLoadBlock("Casos", loadCasesForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Eventos", loadEventsForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Usuarios", loadUsersForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Recepción de mercancía", loadReceptionGoodsForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Stickers de separación", loadReceptionStickersForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Proyectos", loadProjectOrdersForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Reportes/Novedades", loadReportsForRole),
    cutOnly?Promise.resolve([]):safeLoadBlock("Inventario de chipas", loadInventoryChipsForRole)
  ]).then(function(res){
    state.cases=filterCasesForCurrentUserStrict(res[0]||[]);
    state.events=res[1]||[];
    state.users=res[2]||[];
    state.receptions=res[3]||[];
    state.receptionStickers=res[4]||[];
    state.projectOrders=res[5]||[];
    state.reports=filterReportsForCurrentUser(res[6]||[]);
    state.inventoryChips=res[7]||[];
    state.dataLoading=false;
    var normalizePromise=autoNormalizeLoadedPvcPveFromCajaToCartera("Normalización al cargar datos V221: PVC/PVE debe ir a Cartera.");
    if(canSeeAll() || isAdminRoleValue(state.user&&state.user.role)){
      autoMigrateLegacyProcesses();
    }
    return normalizePromise.then(function(moved){
      if(moved>0)console.info("[V221] PVC/PVE movidos automáticamente de Caja a Cartera:",moved);
    });
  }).catch(function(e){
    state.dataLoading=false;
    throw e;
  });
}


function caseLiveHash(list){
  return (list||[]).map(function(c){
    return [c.id,c.updatedAt||"",c.status||"",c.currentProcess||"",c.assignedRole||"",c.assignedTo||"",(c.assignedUserIds||[]).join(","),c.closedAt||""].join("|");
  }).sort().join("~");
}

function purchaseOrderValue(c){
  return String((c && (c.purchaseOrder || (c.salesHold||{}).purchaseOrder || c.ordenCompra || c.oc)) || "").trim();
}
function caseBaseReference(c){
  return (c && (c.reference || c.pedido || c.caseNumber || c.id)) || "Caso";
}
function caseDisplayTitle(c){
  var ref=caseBaseReference(c), oc=purchaseOrderValue(c);
  return ref + (oc ? " · OC " + oc : "");
}
function caseDisplaySubtitle(c){
  var parts=[];
  if(c && c.client)parts.push(c.client);
  if(c && c.salesAdvisor)parts.push("Asesor: "+c.salesAdvisor);
  if(c && (c.invoiceNumber||c.factura))parts.push("Factura: "+(c.invoiceNumber||c.factura));
  if(c && c.requestedDelivery)parts.push("Entrega solicitada: "+processTitle(c.requestedDelivery));
  return parts.join(" · ") || "Caso operativo";
}
function caseSearchText(c){
  return [caseDisplayTitle(c),c&&c.client,c&&c.assignedName,assignedPeopleText(c),c&&c.createdByName,c&&c.salesAdvisor,c&&c.deliveryType,c&&c.requestedDelivery,c&&c.invoiceNumber,c&&c.factura,c&&c.status,processTitle(c&&c.currentProcess)].join(" ").toLowerCase();
}
function caseSummary(c){
  return caseDisplayTitle(c);
}

function normalizePersonText(v){
  return stripAccents(String(v||"").trim().toLowerCase()).replace(/\s+/g," ");
}
function normalizePersonComparableText(v){
  var s=stripAccents(String(v||"").trim().toLowerCase());
  if(!s)return "";
  if(s.indexOf("@")>=0)s=s.split("@")[0];
  s=s.replace(/[_\.\-]+/g," ");
  s=s.replace(/\b(ei|com|co|electroingenieria|sas|s\s*a\s*s)\b/g," ");
  s=s.replace(/[^a-z0-9]+/g," ").replace(/\s+/g," ").trim();
  return s;
}
function samePersonText(a,b){
  var x=normalizePersonComparableText(a), y=normalizePersonComparableText(b);
  if(!x || !y)return false;
  if(x===y)return true;
  var xp=x.split(" ").filter(Boolean), yp=y.split(" ").filter(Boolean);
  if(!xp.length || !yp.length)return false;
  var small=xp.length<=yp.length?xp:yp;
  var big=xp.length<=yp.length?yp:xp;
  var hits=small.filter(function(t){return big.indexOf(t)>=0;}).length;
  if(small.length===1)return hits===1 && small[0].length>=4;
  return hits>=Math.min(2,small.length);
}
function personKey(uidValue,name,email){
  var uidClean=String(uidValue||"").trim();
  if(uidClean)return "uid:"+uidClean;
  var em=normalizePersonText(email||"");
  if(em)return "email:"+em;
  var nm=normalizePersonText(name||"");
  return nm?"name:"+nm:"";
}
function addPersonToMap(map,uidValue,name,email,role,processKey){
  var rawLabel=String(name||email||uidValue||"").trim();
  if(!rawLabel)return;
  var label=cleanVisiblePersonName(rawLabel);
  if(!label)return;
  var generic=[roleTitle(role),processOwnerTitle(processKey),processTitle(processKey),"Caja","Gerencia","Ventas","Logística / despacho","Administrador / Desarrollador"];
  var labelNorm=normalizePersonText(label);
  if(generic.some(function(x){return x && normalizePersonText(x)===labelNorm;}))return;
  var key=personKey(uidValue,label,email);
  if(!key)return;
  if(!map[key])map[key]={key:key,label:label,email:email||"",role:role||"",processes:{},count:0};
  if(processKey)map[key].processes[processKey]=true;
  if(role && !map[key].role)map[key].role=role;
  map[key].count=Number(map[key].count||0)+1;
}
function caseParticipantMap(c){
  var map={};
  if(!c)return map;
  addPersonToMap(map,c.createdBy,c.createdByName,"",c.createdByRole||"ventas","ventas");
  addPersonToMap(map,"",c.salesAdvisor,"","ventas","ventas");
  addPersonToMap(map,c.assignedUid||c.assignedTo,c.assignedName,"",c.assignedRole,c.currentProcess);
  caseAssignedUsers(c).forEach(function(u){addPersonToMap(map,u.uid,u.name,u.email,u.role||"aux_logistica",c.currentProcess);});
  (c.stateHistory||[]).forEach(function(h){addPersonToMap(map,h.responsibleUid||h.userId,h.responsibleName||h.userName,"",h.responsibleRole||h.userRole,h.process||c.currentProcess);});
  (c.evidence||[]).forEach(function(e){addPersonToMap(map,e.createdBy||e.uploadedBy,e.createdByName||e.uploadedByName||e.responsibleName,"",e.responsibleRole||e.role,e.process||e.processKey||c.currentProcess);});
  Object.keys(c.processStats||{}).forEach(function(p){
    var st=c.processStats[p]||{};
    (st.responsibles||[]).forEach(function(r){addPersonToMap(map,r.uid||r.userId,r.name||r.userName,r.email,r.role,p);});
  });
  (c.requirements||[]).forEach(function(r){
    addPersonToMap(map,r.sentBy||r.sentByUid,r.sentByName,"",r.sentByRole,r.source||r.sourceProcess||c.currentProcess);
    addPersonToMap(map,r.answeredBy||r.answeredByUid,r.answeredByName,"",r.answeredByRole,r.returnProcess||r.sourceProcess||c.currentProcess);
  });
  if(c.openRequirement)addPersonToMap(map,c.openRequirement.sentBy,c.openRequirement.sentByName,"",c.openRequirement.sentByRole,c.openRequirement.returnProcess||c.currentProcess);
  (c.cutRequests||[]).forEach(function(x){
    addPersonToMap(map,x.takenBy||x.takenByUid,x.takenByName||x.responsable,"",x.takenByRole,"corte_cable");
    addPersonToMap(map,x.finishedBy||x.finishedByUid,x.finishedByName,"",x.finishedByRole,"corte_cable");
    addPersonToMap(map,x.approvedBy||x.approvedByUid,x.approvedByName,"",x.approvedByRole,"corte_cable");
  });
  return map;
}
function caseParticipantList(c){
  var map=caseParticipantMap(c);
  return Object.keys(map).map(function(k){return map[k];}).sort(function(a,b){return a.label.localeCompare(b.label);});
}
function caseResponsibleNames(c){
  var names=caseParticipantList(c).map(function(x){return cleanVisiblePersonName(x.label);}).filter(Boolean);
  return uniqueArray(names).join(" · ") || "Sin responsable individual registrado";
}
function personMatchesSelected(person,userKey){
  if(!userKey)return true;
  if(person.key===userKey)return true;
  var selected=(kpiUserOptions().filter(function(u){return u.key===userKey;})[0]||{});
  var needles=[userKey.replace(/^(uid|email|name):/,""),selected.label||"",selected.email||""].map(normalizePersonText).filter(Boolean);
  return needles.some(function(n){return normalizePersonText(person.label)===n || normalizePersonText(person.email)===n || normalizePersonText(person.key.replace(/^(uid|email|name):/,""))===n;});
}
function caseMatchesKpiUser(c,userKey){
  if(!userKey)return true;
  return caseParticipantList(c).some(function(person){return personMatchesSelected(person,userKey);});
}
function caseProcessResponsibleNames(c,processKey){
  var names=[];
  caseParticipantList(c).forEach(function(p){if(!processKey || (p.processes&&p.processes[processKey]))names.push(p.label);});
  return uniqueArray(names).join(" · ") || "Sin responsable individual registrado";
}
function kpiUserOptions(){
  var map={};
  (state.users||[]).forEach(function(u){addPersonToMap(map,u.uid||u.id,u.name||u.displayName,u.email,u.role,"");});
  (state.cases||[]).forEach(function(c){
    var m=caseParticipantMap(c);
    Object.keys(m).forEach(function(k){if(!map[k])map[k]=m[k];});
  });
  return Object.keys(map).map(function(k){return map[k];}).sort(function(a,b){return a.label.localeCompare(b.label);});
}
function processUserRows(data,userKey){
  var acc={};
  data.forEach(function(c){
    FLOW.forEach(function(p){
      var touched=(c.currentProcess===p)||(c.processStats&&c.processStats[p]);
      if(!touched)return;
      caseParticipantList(c).forEach(function(person){
        if(userKey && !personMatchesSelected(person,userKey))return;
        if(!(person.processes&&person.processes[p]))return;
        var key=person.key+"|"+p;
        if(!acc[key])acc[key]={user:person.label,role:person.role||"",process:p,processName:processTitle(p),cases:{},open:0,closed:0,requirements:0,cuts:0,active:0,wait:0,dead:0};
        acc[key].cases[c.id]=true;
        if(c.closedAt)acc[key].closed++; else acc[key].open++;
        if(c.requirements){c.requirements.forEach(function(r){if(r.source===p||r.sourceProcess===p)acc[key].requirements++;});}
        if(p==="corte_cable")acc[key].cuts+=(c.cutRequests||[]).length;
        var st=(c.processStats||{})[p]||{};
        acc[key].active+=Number(st.activeMs||0);acc[key].wait+=Number(st.waitMs||0);acc[key].dead+=Number(st.deadMs||0);
      });
    });
  });
  return Object.keys(acc).map(function(k){var r=acc[k];r.count=Object.keys(r.cases).length;r.total=r.active+r.wait+r.dead;r.avg=r.count?r.total/r.count:0;return r;}).sort(function(a,b){return a.user.localeCompare(b.user)||a.processName.localeCompare(b.processName);});
}
function flowTraceTypeLabel(type){
  var t=String(type||"");
  var map={
    creacion:"Creación",valor:"Valor agregado",handoff:"Cambio de etapa",asignado:"Asignación",asignacion:"Asignación",espera:"Requerimiento / espera",cierre:"Cierre",cancelacion:"Cancelación",no_entregado:"No entrega",devolucion_caja:"Devolución a Caja",solucion_entrega:"Solución logística",evidencia:"Evidencia",evento:"Evento",partial_shipment:"Envío parcial"
  };
  if(map[t])return map[t];
  if(t.indexOf("CASE_CREATED")>=0)return "Creación";
  if(t.indexOf("TRANSFER")>=0)return "Cambio de etapa";
  if(t.indexOf("REQUIREMENT")>=0)return "Requerimiento";
  if(t.indexOf("NO_DELIVERY")>=0)return "No entrega";
  if(t.indexOf("REPORT")>=0 || t.indexOf("NOVEDAD")>=0)return "Novedad";
  if(t.indexOf("EVIDENCE")>=0)return "Evidencia";
  if(t.indexOf("CLOSED")>=0 || t.indexOf("CERRADO")>=0)return "Cierre";
  return eventKindLabel(t)||t.replace(/_/g," ");
}
function flowTraceDetailFromEvent(e){
  return e.detail||e.reason||e.description||eventMessage(e)||e.type||"Movimiento registrado";
}
function flowTraceKey(row){
  return [row.rawAt||row.fecha||"",normalizePersonText(row.proceso||""),normalizePersonText(row.usuario||""),normalizePersonText(row.tipo||""),normalizePersonText(row.detalle||"")].join("|");
}
function appendFlowTraceFromEvent(c,event){
  if(!c||!event)return;
  c.stateHistory=c.stateHistory||[];
  var type=event.type||"evento";
  var process=event.process||event.currentProcess||c.currentProcess||"";
  var detail=flowTraceDetailFromEvent(event);
  var actorName=(state.user&&state.user.name)||event.userName||event.createdByName||"Sistema";
  var actorRole=(state.user&&state.user.role)||event.createdByRole||event.sourceRole||"";
  var ts=event.timestamp||now();
  var trace={id:uid("ST"),timestamp:ts,process:process,processName:processTitle(process),status:c.status||"",type:type,traceType:flowTraceTypeLabel(type),detail:detail,responsibleUid:(state.user&&state.user.uid)||event.userId||event.createdBy||"",responsibleName:actorName,responsibleRole:actorRole,source:"case_event"};
  var key=flowTraceKey({rawAt:trace.timestamp,proceso:trace.processName,usuario:trace.responsibleName,tipo:trace.traceType,detalle:trace.detail});
  var exists=(c.stateHistory||[]).slice(-8).some(function(h){
    var hk=flowTraceKey({rawAt:h.timestamp||h.createdAt,proceso:processTitle(h.process||process),usuario:h.responsibleName||h.userName||"",tipo:flowTraceTypeLabel(h.traceType||h.type),detalle:h.detail||""});
    return hk===key;
  });
  if(!exists)c.stateHistory.push(trace);
  if(c.stateHistory.length>700)c.stateHistory=c.stateHistory.slice(-700);
  registerProcessResponsible(c,process,state.user||{uid:event.userId||event.createdBy,name:event.userName||event.createdByName,role:event.createdByRole||event.sourceRole},type);
}
function caseTraceRows(c){
  var rows=[], seen={};
  function add(row){
    row=row||{};
    row.rawAt=row.rawAt||row.fechaRaw||row.timestamp||row.createdAt||"";
    row.fecha=row.fecha||fmtDate(row.rawAt);
    row.proceso=row.proceso||processTitle(row.process||c.currentProcess);
    row.usuario=row.usuario||"";
    row.rol=row.rol||"";
    row.tipo=row.tipo||"Movimiento";
    row.detalle=row.detalle||"";
    var k=flowTraceKey(row);
    if(seen[k])return;
    seen[k]=true;rows.push(row);
  }
  (c.stateHistory||[]).forEach(function(h){add({rawAt:h.timestamp||h.createdAt,proceso:processTitle(h.process||c.currentProcess),usuario:h.responsibleName||h.userName||"",rol:roleTitle(h.responsibleRole||h.userRole||""),tipo:flowTraceTypeLabel(h.traceType||h.type),detalle:h.detail||""});});
  (state.events||[]).filter(function(e){return e.caseId===c.id;}).forEach(function(e){add({rawAt:e.timestamp||e.createdAt,proceso:e.processName||processTitle(e.currentProcess||e.process||c.currentProcess),usuario:e.userName||e.createdByName||"",rol:roleTitle(e.createdByRole||e.sourceRole||e.role||""),tipo:flowTraceTypeLabel(e.type),detalle:flowTraceDetailFromEvent(e)});});
  (c.requirements||[]).forEach(function(r){add({rawAt:r.sentAt||r.createdAt||r.updatedAt,proceso:processTitle(r.sourceProcess||r.returnProcess||r.process||c.currentProcess),usuario:r.sentByName||r.createdByName||"",rol:roleTitle(r.sourceRole||""),tipo:"Requerimiento",detalle:(r.reason||"Requerimiento")+(r.detail?" · "+r.detail:"")+(r.status?" · Estado: "+r.status:"")});});
  if(c.openRequirement){var r=c.openRequirement;add({rawAt:r.sentAt||c.updatedAt,proceso:processTitle(r.returnProcess||c.currentProcess),usuario:r.sentByName||"",rol:roleTitle(r.sourceRole||""),tipo:"Requerimiento activo",detalle:(r.reason||"Requerimiento activo")+(r.detail?" · "+r.detail:"")});}
  (c.noDeliveryReports||[]).forEach(function(rep){
    add({rawAt:rep.createdAt,proceso:processTitle(rep.targetProcess||c.currentProcess),usuario:rep.createdByName||"",rol:"Ventas",tipo:"No entrega",detalle:rep.detail||"Pedido confirmado como no entregado"});
    (rep.history||[]).forEach(function(h){add({rawAt:h.at||h.timestamp,proceso:processTitle(rep.targetProcess||c.currentProcess),usuario:h.by||"",rol:"",tipo:flowTraceTypeLabel(h.action||"no_entregado"),detalle:h.detail||h.action||"Gestión no entrega"});});
  });
  (c.evidence||[]).forEach(function(ev){add({rawAt:ev.uploadedAt||ev.createdAt,proceso:ev.processName||processTitle(ev.processKey||ev.process||c.currentProcess),usuario:ev.createdByName||ev.uploadedBy||"",rol:roleTitle(ev.responsibleRole||""),tipo:"Evidencia",detalle:(ev.detail||ev.fileName||ev.name||"Soporte cargado")});});
  Object.keys(c.deliveryEvidence||{}).forEach(function(k){var ev=c.deliveryEvidence[k];if(ev)add({rawAt:ev.uploadedAt||ev.createdAt,proceso:processTitle(c.currentProcess),usuario:ev.uploadedBy||ev.createdByName||"",rol:"",tipo:"Evidencia entrega",detalle:(ev.detail||ev.fileName||ev.name||k)});});
  if(!rows.length)add({rawAt:c.createdAt,proceso:processTitle(c.currentProcess),usuario:caseResponsibleNames(c),rol:roleTitle(c.assignedRole||c.createdByRole||""),tipo:c.status||"Inicio",detalle:c.description||""});
  return rows.sort(function(a,b){return new Date(a.rawAt||0)-new Date(b.rawAt||0);});
}
function caseFlowTrace(c){
  return caseTraceRows(c).map(function(r){return [r.fecha,r.proceso,r.usuario,r.rol,r.tipo,r.detalle];});
}
function flowTracePanel(c){
  var rows=caseTraceRows(c);
  return '<h3 style="margin-top:18px">Rastro completo del flujo</h3><p class="muted">Registro cronológico de creación, asignaciones, cambios de etapa, requerimientos, no entregas, devoluciones, evidencias y cierres.</p><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Proceso</th><th>Usuario</th><th>Rol</th><th>Tipo</th><th>Detalle</th></tr></thead><tbody>'+rows.map(function(r){return '<tr><td>'+esc(r.fecha)+'</td><td>'+esc(r.proceso)+'</td><td>'+esc(r.usuario||'Sistema')+'</td><td>'+esc(r.rol||'')+'</td><td>'+esc(r.tipo)+'</td><td>'+esc(r.detalle||'')+'</td></tr>';}).join('')+'</tbody></table></div>';
}

