function caseRelevantToCurrentUser(c){
  if(!state.user || !c)return false;
  if(shouldHideFromCajaBecauseCartera(c))return false;
  if(shouldShowToCarteraDespiteCaja(c))return true;
  if(canSeeAll()||canAuditViewAll())return true;
  if(!currentUserAllowedByDeliveryRoute(c))return false;
  if(currentUserBlockedByAssignment(c))return false;
  var r=normalizeRole(state.user.role);
  var aliases=roleQueryAliases(state.user.role).map(normalizeRole);
  if(normalizeRole(c.assignedRole)===r || c.assignedTo===state.user.uid || c.assignedUid===state.user.uid || c.createdBy===state.user.uid)return true;
  if(Array.isArray(c.assignedUserIds) && c.assignedUserIds.indexOf(state.user.uid)>=0)return true;
  if(r==="auxiliar_corte" && c.hasCuts===true)return true;
  return canAccessProcess(r,c.currentProcess);
}
function filterCasesForCurrentUserStrict(list){
  list=sortByUpdated(uniqueById(list||[]));
  if(canSeeAll()||canAuditViewAll())return list;
  return list.filter(caseRelevantToCurrentUser);
}


function shouldAutoRenderNow(){
  var d=qs("#drawer");
  if(d && d.classList.contains("open"))return false;
  var a=document.activeElement;
  if(a && /INPUT|TEXTAREA|SELECT/.test(a.tagName||""))return false;
  return true;
}
function isMobileRuntime(){
  try{return (window.innerWidth||document.documentElement.clientWidth||999)<=820 || /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent||"");}
  catch(e){return false;}
}
function isCutRuntimeUser(){
  return normalizeRole(state.user&&state.user.role)==="auxiliar_corte" || isCutRoleRuntimeUser();
}
function cleanupProtectedToast(){
  try{
    var box=document.getElementById("ei-live-toast");
    if(!box)return;
    var txt=String(box.textContent||"");
    if(/Sincronización silenciosa|Actualizar vista|Actualización silenciosa/i.test(txt)){
      box.style.display="none";
      box.innerHTML="";
      clearTimeout(box.__hideTimer);
    }
  }catch(e){novaCaptureError(e,"operación heredada");}
}
function mobileSilentLiveUpdate(){
  state.realtime.pendingRender=false;
  cleanupProtectedToast();
  if(isCutRuntimeUser()){
    state.route="corte_cable";
    if(!qs("#drawer") || !qs("#drawer").classList.contains("open")){
      try{renderCutsQueue();}catch(e){try{render();}catch(x){novaCaptureError(x,"operación heredada");}}
    }
    return true;
  }
  return false;
}


function renderAfterLiveChange(){
  if(!state.user)return;
  cleanupProtectedToast();
  if(isMobileRuntime()){
    if(state.detailId){
      var still=caseById(state.detailId);
      if(still)cacheDetailCase(still);
      state.realtime.pendingRender=false;
      return;
    }
    if(!shouldAutoRenderNow()){
      state.realtime.pendingRender=false;
      return;
    }
    if(mobileSilentLiveUpdate())return;
    try{render();}catch(e){console.warn("No se pudo repintar móvil",e);}
    return;
  }
  if(state.detailId){
    var c=caseById(state.detailId);
    if(c)cacheDetailCase(c);
    state.realtime.pendingRender=false;
    return;
  }
  if(!shouldAutoRenderNow()){
    state.realtime.pendingRender=false;
    return;
  }
  if(state.realtime.renderTimer)clearTimeout(state.realtime.renderTimer);
  state.realtime.renderTimer=setTimeout(function(){
    state.realtime.renderTimer=null;
    if(!shouldAutoRenderNow()){state.realtime.pendingRender=false;return;}
    try{render();}catch(e){console.warn("No se pudo repintar en vivo",e);}
  },260);
}

function forceProtectedViewRefresh(){
  if(v251ProtectedContext()){
    state.v251.deferredRefresh=true;

    showLiveToast(
      "Vista protegida",
      "La aplicación no cerrará el pedido o formulario activo. La lista se actualizará al terminar.",
      false
    );

    return Promise.resolve(false);
  }

  return v251BackgroundRefreshCases(
    "actualización solicitada"
  ).then(function(){
    v251ApplyPendingView();
    return true;
  }).catch(function(error){
    console.warn(
      "[V254] Actualización manual pendiente.",
      error
    );
    return false;
  });
}
function showLiveToast(title,msg,withButton){
  var titleText=String(title||""), msgText=String(msg||"");
  if(isMobileRuntime() && (withButton || /Sincronización silenciosa|Actualización silenciosa/i.test(titleText+msgText))){
    state.realtime.pendingRender=false;
    cleanupProtectedToast();
    return;
  }
  var box=document.getElementById("ei-live-toast");
  if(!box){
    box=document.createElement("div");
    box.id="ei-live-toast";
    box.style.cssText="position:fixed;left:12px;right:12px;bottom:84px;z-index:2147483647;max-width:520px;margin:auto;background:#061b46;color:#fff;border-radius:20px;box-shadow:0 20px 60px rgba(6,27,70,.32);padding:14px 14px 12px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;display:none;pointer-events:auto";
    document.body.appendChild(box);
  }
  box.innerHTML='<div style="font-weight:900;font-size:14px;margin-bottom:4px">'+esc(title||"Movimiento detectado")+'</div><div style="font-size:12px;line-height:1.35;opacity:.9">'+esc(msg||"")+'</div>'+(withButton?'<button id="ei-live-refresh-btn" type="button" style="margin-top:10px;border:0;background:#ffda37;color:#061b46;border-radius:12px;padding:10px 14px;font-weight:900;cursor:pointer;min-height:42px;touch-action:manipulation">Actualizar vista</button>':'');
  box.style.display="block";
  var btn=document.getElementById("ei-live-refresh-btn");
  if(btn){btn.onclick=function(ev){if(ev)ev.preventDefault();forceProtectedViewRefresh();};}
  clearTimeout(box.__hideTimer);
  box.__hideTimer=setTimeout(function(){box.style.display="none";},withButton?9000:4500);
}



function eventIsOwn(e){
  return !!(state.user && e && (e.createdBy===state.user.uid || e.userId===state.user.uid));
}

function eventProcessKey(e){
  return String((e&&(e.currentProcess||e.process))||"").trim();
}

function eventIsDispatchProcess(e){
  var p=eventProcessKey(e);
  return ["despacho_local","despacho_nacional","cierre_despacho_nacional","cliente_punto","cliente_recoge"].indexOf(p)>=0;
}

function eventActorRole(e){
  return normalizeRole((e&&(e.createdByRole||e.sourceRole||e.role)) || (state.user&&state.user.role) || "");
}

function eventActorIsLogistics(e){
  var r=eventActorRole(e);
  return ["lider_logistico","coordinador_logistico","aux_logistica","jefe_logistica"].indexOf(r)>=0;
}

function eventTypeIsRequirement(t){
  return t.indexOf("REQUIREMENT")>=0 || t==="BOX_HOLD_TO_SALES" || t==="NO_DELIVERY_REQUIREMENT" || t.indexOf("_TO_SALES")>=0 || t.indexOf("REQUERIMIENTO")>=0;
}

function eventTypeIsReport(t){
  return t.indexOf("REPORT")>=0 || t==="GOODS_RECEPTION_REPORT" || t==="NON_CONFORMITY_REPORTED" || t.indexOf("NOVEDAD")>=0;
}

function eventTypeIsOrderCreated(t){
  return t==="CASE_CREATED" || t==="PROJECT_ORDER_TO_CASE" || t==="PENDING_ITEMS_RESENT";
}

function eventTypeIsChecklistClosed(t){
  return t==="CHECKLIST_CLOSED" || t==="CHECK_CLOSED" || t==="CHECKLIST_COMPLETED";
}

function eventTypeIsClosed(t){
  if(eventTypeIsChecklistClosed(t))return false;
  return t.indexOf("CASE_CLOSED")>=0 || t==="GOODS_RECEPTION_CLOSED" || t.indexOf("CLOSED")>=0 || t.indexOf("CERRADO")>=0;
}

function soundKeyForEvent(e){
  var t=String((e&&e.type)||"").toUpperCase();
  if(!t)return "general";

  // Cerrar checklist no es cerrar caso. Debe sonar únicamente el audio de chequeo.
  if(eventTypeIsChecklistClosed(t))return "checklistClosed";

  if(eventIsOwn(e)){
    if(eventTypeIsClosed(t) && eventIsDispatchProcess(e) && eventActorIsLogistics(e))return "logisticsClosed";
    if(eventTypeIsRequirement(t))return "createdRequirement";
    if(eventTypeIsReport(t))return "createdReport";
    if(eventTypeIsOrderCreated(t))return "createdOrder";
  }

  if(eventTypeIsRequirement(t))return "requirement";
  if(eventTypeIsReport(t))return "report";
  if(eventTypeIsOrderCreated(t))return "newOrder";
  if(eventTypeIsClosed(t))return "closed";
  return "general";
}

function playAudioAsset(src,volume){
  if(!src)return;
  try{
    var audio=new Audio(src);
    audio.preload="auto";
    audio.volume=Math.max(0,Math.min(1,volume==null?0.72:volume));
    var p=audio.play();
    if(p&&p.catch)p.catch(function(){try{playBeep();}catch(e){novaCaptureError(e,"operación heredada");}});
  }catch(e){try{playBeep();}catch(x){novaCaptureError(x,"operación heredada");}}
}

function playNotificationSound(kind){
  kind=kind||"general";
  // El checklist tiene audio propio y no debe mezclar sonido general ni cierre de caso.
  if(kind==="checklistClosed"){
    playAudioAsset(notificationAssets.checklistClosed,0.92);
    return;
  }
  playAudioAsset(notificationAssets.general,0.58);
  if(kind && kind!=="general")setTimeout(function(){playAudioAsset(notificationAssets[kind],0.92);},260);
}

function showUploadFeedback(mode,msg){
  var box=document.getElementById("ei-upload-feedback");
  if(!box){
    box=document.createElement("div");
    box.id="ei-upload-feedback";
    document.body.appendChild(box);
  }
  var isSuccess=mode==="success", isWarning=mode==="warning", isError=mode==="error";
  var img=isSuccess?feedbackAssets.success:feedbackAssets.loading;
  var title=isSuccess?"Carga completada":(isWarning?"Carga pendiente":(isError?"Carga no completada":"Cargando archivo"));
  var text=msg||(isSuccess?"La evidencia quedó guardada correctamente.":(isWarning?"El flujo continúa y la evidencia queda pendiente de reintento.":(isError?"No fue posible cargar el archivo. Intente nuevamente.":"Estamos subiendo el soporte. No cierre esta ventana.")));
  box.className="ei-upload-feedback show "+(isSuccess?"success":(isWarning?"warning":(isError?"error":"loading")));
  box.innerHTML='<div class="ei-upload-feedback-card"><img src="'+esc(img)+'" alt=""><strong>'+esc(title)+'</strong><span>'+esc(text)+'</span></div>';
  clearTimeout(box.__timer);
  if(isSuccess||isWarning||isError){box.__timer=setTimeout(hideUploadFeedback,(isSuccess?1800:3600));}
}

function hideUploadFeedback(){
  var box=document.getElementById("ei-upload-feedback");
  if(!box)return;
  box.classList.remove("show");
  clearTimeout(box.__timer);
}

function uniqueArray(arr){
  var out=[];
  (arr||[]).forEach(function(x){x=normalizeRole(x||"");if(x && out.indexOf(x)<0)out.push(x);});
  return out;
}

function notificationVisibleRolesForEvent(c,event){
  var roles=[];
  if(c){
    roles.push(c.assignedRole,c.createdByRole);
    if(c.currentProcess)roles.push(primaryOwnerRole(c.currentProcess));
    if(c.openRequirement){roles.push(c.openRequirement.targetRole,c.openRequirement.sourceRole);}
  }
  if(event){
    roles.push(event.assignedRole,event.targetRole,event.sourceRole,event.role,event.createdByRole,event.toRole,event.fromRole);
    if(event.process)roles.push(primaryOwnerRole(event.process));
  }
  return uniqueArray(roles);
}

function enrichCaseEvent(c,event){
  event=event||{};
  var visible=notificationVisibleRolesForEvent(c,event);
  return Object.assign({
    caseReference:(c&&(c.reference||c.pedido||c.caseNumber))||"",
    caseClient:(c&&c.client)||"",
    caseStatus:(c&&c.status)||"",
    currentProcess:(c&&c.currentProcess)||event.process||"",
    processName:processTitle((c&&c.currentProcess)||event.process),
    assignedRole:(c&&c.assignedRole)||event.assignedRole||"",
    assignedTo:(c&&(c.assignedTo||c.assignedUid))||"",
    sourceRole:state.user?state.user.role:"",
    createdBy:state.user?state.user.uid:"",
    createdByRole:state.user?state.user.role:"",
    visibleRoles:visible
  },event);
}

function eventHash(list){
  return (list||[]).map(function(e){return [e.id,e.timestamp||"",e.type||"",e.caseId||"",e.detail||e.reason||""].join("|");}).sort().join("~");
}

function eventRelevantToCurrentUser(e){
  if(!state.user || !e)return false;
  if(userIsGlobalVisibilityRole())return true;
  return eventBelongsToCurrentAreaStrict(e);
}

function eventKindLabel(type){
  var map={
    CASE_CREATED:"Pedido creado",
    CASE_ACCEPTED:"Caso aceptado",
    TRANSFER_SENT:"Cambio de etapa",
    CHECK_UPDATED:"Checklist actualizado",
    CHECKLIST_CLOSED:"Checklist cerrado",
    NON_CONFORMITY_REPORTED:"Inconformidad reportada",
    REQUIREMENT_SENT:"Requerimiento generado",
    REQUIREMENT_ANSWERED:"Requerimiento respondido",
    EVIDENCE_UPLOADED:"Evidencia cargada",
    DELIVERY_EVIDENCE_UPLOADED:"Evidencia de entrega cargada",
    LOGISTICS_READY_FOR_CARRIER:"Logística finalizada · espera transportadora",
    CUT_REGISTERED:"Corte registrado",
    CUT_STARTED:"Corte iniciado",
    CUT_FINISHED:"Corte finalizado",
    SIESA_FLAT_FILE_CUT_EXPORTED:"Registro histórico completado",
    CASE_CLOSED:"Caso cerrado",
    MANAGER_APPROVED:"Gerencia aprobó",
    MANAGER_REJECTED:"Gerencia rechazó",
    USER_CREATED:"Usuario creado",
    CASE_DELETED_ADMIN:"Caso eliminado",
    PARTIAL_SHIPMENT_CREATED:"Envío parcial creado",
    PARTIAL_SHIPMENT_SENT_TO_BILLING:"Envío parcial a facturación",
    NO_DELIVERY_REQUIREMENT:"Pedido no entregado",
    NO_DELIVERY_LOGISTICS_SOLUTION:"Solución logística no entrega",
    NO_DELIVERY_REFUND_TO_BOX:"Devolución a Caja por no entrega",
    NO_DELIVERY_CLOSED:"No entrega cerrada",
    NO_DELIVERY_REFUND_TO_BOX:"Devolución a Caja por no entrega",
    NO_DELIVERY_LOGISTICS_SOLUTION:"Solución logística no entrega",
    BOX_HOLD_TO_SALES:"Retenido enviado a Ventas",
    BOX_HOLD_CLOSED:"Retenido cerrado por Caja",
    BOX_HOLD_SOLVED:"Retenido gestionado",
    DELIVERY_CONFIRMED:"Entrega confirmada",
    REPORT_CREATED:"Novedad creada"
  };
  return map[type]||String(type||"Movimiento").replace(/_/g," ");
}

function eventMessage(e){
  var ref=e.caseReference||e.pedido||e.caseNumber||e.caseId||"Caso";
  var proc=e.processName||processTitle(e.currentProcess||e.process)||"";
  var det=e.detail||e.reason||"";
  return ref+(proc?" · "+proc:"")+(det?" · "+det:"");
}

function dispatchNotification(title,msg,forceSound,event){
  showLiveToast(title,msg,false);
  var nowMs=Date.now();
  if(canNotify() && Notification.permission==="granted"){
    try{new Notification(title,{body:msg,icon:appResource("shared/assets/app-icon.svg"),badge:appResource("shared/assets/app-icon.svg"),tag:"ei-logistica-"+title,renotify:true});}catch(e){novaCaptureError(e,"operación heredada");}
  }
  if(forceSound || !(canNotify() && Notification.permission==="granted")){
    if(nowMs-(state.notifications.lastSoundAt||0)>900){state.notifications.lastSoundAt=nowMs;playNotificationSound(soundKeyForEvent(event));}
  }
}

function queueEventNotification(e){
  if(!e || !e.id || !eventRelevantToCurrentUser(e))return;
  if(state.realtime.startedAt && Date.now()-state.realtime.startedAt<2500)return;
  var key=e.id+"_"+(e.timestamp||"");
  if(state.notifications.memory[key])return;
  state.notifications.memory[key]=true;
  state.notifications.queue.push(e);
  clearTimeout(state.notifications.queueTimer);
  state.notifications.queueTimer=setTimeout(flushEventNotifications,700);
}

function flushEventNotifications(){
  var q=state.notifications.queue.splice(0);
  if(!q.length)return;
  if(q.length===1){
    var e=q[0];
    dispatchNotification(eventKindLabel(e.type),eventMessage(e),true,e);
    return;
  }
  var ref=q[0].caseReference||q[0].caseId||"el sistema";
  dispatchNotification("Nuevos movimientos",q.length+" movimientos registrados. Último: "+eventMessage(q[q.length-1]),true,q[q.length-1]);
}

function applyRealtimeEvents(list){
  list=(list||[]).filter(eventRelevantToCurrentUser).sort(function(a,b){return new Date(b.timestamp||0)-new Date(a.timestamp||0);});
  var h=eventHash(list);
  if(!state.realtime.initialEventsLoaded){
    state.events=list;
    state.realtime.lastEventHash=h;
    state.realtime.initialEventsLoaded=true;
    (list||[]).slice(0,60).forEach(function(e){if(e&&e.id)state.notifications.memory[e.id+"_"+(e.timestamp||"")]=true;});
    return;
  }
  if(h===state.realtime.lastEventHash)return;
  var old={};
  (state.events||[]).forEach(function(e){if(e&&e.id)old[e.id]=true;});
  state.events=list;
  state.realtime.lastEventHash=h;
  list.forEach(function(e){if(!old[e.id])queueEventNotification(e);});
  renderAfterLiveChange();
}

function rebuildRealtimeEventsFromBuckets(){
  var all=[];
  Object.keys(state.realtime.eventBuckets||{}).forEach(function(k){all=all.concat(state.realtime.eventBuckets[k]||[]);});
  applyRealtimeEvents(uniqueById(all));
}

function addEventRealtimeListener(key,query){
  try{
    var unsub=query.onSnapshot(function(snap){
      state.realtime.eventBuckets[key]=docsToList(snap);
      rebuildRealtimeEventsFromBuckets();
    },function(err){console.warn("Escucha de notificaciones falló",key,err);});
    state.realtime.eventUnsubs.push(unsub);
  }catch(e){console.warn("No se pudo activar listener de notificaciones",key,e);}
}

function startNotificationListeners(){
  if(!db || !state.user)return;
  if(canSeeAll()||canAuditViewAll()){
    addEventRealtimeListener("events_all",db.collection("case_events").orderBy("timestamp","desc").limit(200));
    return;
  }
  addEventRealtimeListener("events_user",db.collection("case_events").where("userId","==",state.user.uid).limit(100));
  addEventRealtimeListener("events_created",db.collection("case_events").where("createdBy","==",state.user.uid).limit(100));
  addEventRealtimeListener("events_assigned_uid",db.collection("case_events").where("assignedUid","==",state.user.uid).limit(100));
  roleQueryAliases(state.user.role).forEach(function(r){
    addEventRealtimeListener("events_target_"+r,db.collection("case_events").where("targetRole","==",r).limit(100));
    addEventRealtimeListener("events_assigned_"+r,db.collection("case_events").where("assignedRole","==",r).limit(100));
    addEventRealtimeListener("events_visible_"+r,db.collection("case_events").where("visibleRoles","array-contains",r).limit(100));
  });
}

function notifyRealtimeChanges(newList, oldList){
  var oldMap={};
  (oldList||[]).forEach(function(c){if(c&&c.id)oldMap[c.id]=c;});
  var changes=[];
  (newList||[]).forEach(function(c){
    if(!c || !c.id || !caseRelevantToCurrentUser(c))return;
    var old=oldMap[c.id];
    if(!old){changes.push({type:"nuevo",c:c,msg:"Nuevo caso visible: "+caseSummary(c)+"."});return;}
    if((old.currentProcess||"") !== (c.currentProcess||"")){
      changes.push({type:"proceso",c:c,msg:caseSummary(c)+" pasó de "+processTitle(old.currentProcess)+" a "+processTitle(c.currentProcess)+"."});return;
    }
    if((old.status||"") !== (c.status||"")){
      changes.push({type:"estado",c:c,msg:caseSummary(c)+" cambió de estado a "+(c.status||"sin estado")+"."});return;
    }
    if((old.assignedRole||"") !== (c.assignedRole||"") || (old.assignedTo||"") !== (c.assignedTo||"")){
      changes.push({type:"asignacion",c:c,msg:caseSummary(c)+" fue reasignado a "+roleTitle(c.assignedRole)+"."});return;
    }
  });
  if(!changes.length)return;
  var nowMs=Date.now();
  if(state.realtime.startedAt && nowMs-state.realtime.startedAt<3000)return;
  if(nowMs - (state.realtime.lastChangeAt||0) < 1200)return;
  state.realtime.lastChangeAt=nowMs;
  var title=changes.length===1?"Movimiento detectado":"Movimientos detectados";
  var msg=changes.length===1?changes[0].msg:(changes.length+" casos tuvieron cambios. Actualizando la vista.");
  showLiveToast(title,msg,false);
  if(canNotify() && Notification.permission==="granted"){
    try{new Notification(title,{body:msg,icon:appResource("shared/assets/app-icon.svg"),badge:appResource("shared/assets/app-icon.svg")});}catch(e){novaCaptureError(e,"operación heredada");}
  }else{
    playNotificationSound((changes.length===1 && changes[0].type==="nuevo")?"newOrder":"general");
  }
}

function applyRealtimeCases(list){
  list=sortByUpdated(uniqueById(list||[]));
  var newHash=caseLiveHash(list);
  if(!state.realtime.initialCasesLoaded){
    state.cases=list;
    if(state.detailId){var firstDetail=caseById(state.detailId);if(firstDetail)cacheDetailCase(firstDetail);}
    state.realtime.lastHash=newHash;
    state.realtime.initialCasesLoaded=true;
    if(canSeeAll() || isAdminRoleValue(state.user&&state.user.role))autoMigrateLegacyProcesses();
    return;
  }
  if(newHash===state.realtime.lastHash)return;
  var oldList=state.cases.slice();
  state.cases=list;
  if(state.detailId){var liveDetail=caseById(state.detailId);if(liveDetail)cacheDetailCase(liveDetail);}
  state.realtime.lastHash=newHash;
  if(canSeeAll() || isAdminRoleValue(state.user&&state.user.role))autoMigrateLegacyProcesses();
  notifyRealtimeChanges(list,oldList);
  renderAfterLiveChange();
}

function rebuildRealtimeFromBuckets(){
  var all=[];
  Object.keys(state.realtime.buckets||{}).forEach(function(k){all=all.concat(state.realtime.buckets[k]||[]);});
  applyRealtimeCases(all);
}

function addCaseRealtimeListener(key,query){
  try{
    var unsub=query.onSnapshot(function(snap){
      state.realtime.buckets[key]=docsToList(snap);
      rebuildRealtimeFromBuckets();
    },function(err){
      console.warn("Escucha en tiempo real falló",key,err);
      if(!(isMobileRuntime()||isCutRuntimeUser()))showLiveToast("Conexión en tiempo real intermitente","La app seguirá actualizando automáticamente cada 25 segundos.",false);
    });
    state.realtime.caseUnsubs.push(unsub);
  }catch(e){console.warn("No se pudo activar listener",key,e);}
}

function stopRealtimeSync(){
  try{(state.realtime.caseUnsubs||[]).forEach(function(fn){try{fn();}catch(e){novaCaptureError(e,"operación heredada");}});}catch(e){novaCaptureError(e,"operación heredada");}
  try{if(state.realtime.eventUnsub)state.realtime.eventUnsub();}catch(e){novaCaptureError(e,"operación heredada");}
  try{(state.realtime.eventUnsubs||[]).forEach(function(fn){try{fn();}catch(e){novaCaptureError(e,"operación heredada");}});}catch(e){novaCaptureError(e,"operación heredada");}
  try{if(state.realtime.userUnsub)state.realtime.userUnsub();}catch(e){novaCaptureError(e,"operación heredada");}
  if(state.realtime.pollTimer)clearInterval(state.realtime.pollTimer);
  state.realtime={caseUnsubs:[],eventUnsub:null,eventUnsubs:[],userUnsub:null,pollTimer:null,buckets:{},eventBuckets:{},initialCasesLoaded:false,initialEventsLoaded:false,lastHash:"",lastEventHash:"",lastChangeAt:0,lastEventAt:0,startedAt:0,pendingRender:false};
}

function v242LegacyStartRealtimeSync(){
  if(!firebaseReady || !db || !state.user)return;
  stopRealtimeSync();
  state.realtime.startedAt=Date.now();
  var nr=normalizeRole(state.user.role);
  if(isCutRoleRuntimeUser() || nr==="auxiliar_corte"){
    addCaseRealtimeListener("cuts",db.collection("cases").where("hasCuts","==",true));
    state.realtime.pollTimer=setInterval(function(){
      if(!state.user || !firebaseReady || !db)return;
      loadData().then(function(){
        var h=caseLiveHash(state.cases);
        if(h!==state.realtime.lastHash){
          state.realtime.lastHash=h;
          renderAfterLiveChange();
        }
      }).catch(function(e){console.warn("Refresco silencioso corte falló",e);});
    },25000);
    return;
  }
  if(canSeeAll()||canAuditViewAll()){
    addCaseRealtimeListener("all",db.collection("cases").orderBy("updatedAt","desc"));
  }else{
    if(nr==="auxiliar_corte")addCaseRealtimeListener("cuts",db.collection("cases").where("hasCuts","==",true));
    currentUserIdentityAliases().forEach(function(id){
      addCaseRealtimeListener("created_"+id,db.collection("cases").where("createdBy","==",id));
      addCaseRealtimeListener("assigned_uid_"+id,db.collection("cases").where("assignedUid","==",id));
      addCaseRealtimeListener("assigned_to_"+id,db.collection("cases").where("assignedTo","==",id));
      addCaseRealtimeListener("assigned_userids_"+id,db.collection("cases").where("assignedUserIds","array-contains",id));
    });
    roleQueryAliases(state.user.role).forEach(function(r){
      addCaseRealtimeListener("assigned_"+r,db.collection("cases").where("assignedRole","==",r));
      addCaseRealtimeListener("req_target_"+r,db.collection("cases").where("openRequirement.targetRole","==",r));
      addCaseRealtimeListener("req_assigned_"+r,db.collection("cases").where("openRequirement.assignedRole","==",r));
    });
    var ownerRule=currentUserDeliveryOwnerRule();
    if(ownerRule){
      addCaseRealtimeListener("delivery_owner_"+ownerRule.key,db.collection("cases").where("deliveryRouteOwner","==",ownerRule.key));
      (ownerRule.legacyKeys||[]).forEach(function(k){addCaseRealtimeListener("delivery_owner_legacy_"+k,db.collection("cases").where("deliveryRouteOwner","==",k));});
      ownerRule.routes.forEach(function(routeKey){
        addCaseRealtimeListener("delivery_current_"+routeKey,db.collection("cases").where("currentProcess","==",routeKey));
        addCaseRealtimeListener("delivery_type_"+routeKey,db.collection("cases").where("deliveryType","==",routeKey));
      });
    }
  }
  startNotificationListeners();
  if(canSeeAll()||canAuditViewAll()){
    try{
      state.realtime.userUnsub=db.collection("users").onSnapshot(function(snap){state.users=docsToList(snap);},function(e){console.warn("Usuarios en vivo no disponibles",e);});
    }catch(e){novaCaptureError(e,"operación heredada");}
  }
  state.realtime.pollTimer=setInterval(function(){
    if(!state.user || !firebaseReady || !db)return;
    loadData().then(function(){
      var h=caseLiveHash(state.cases);
      if(h!==state.realtime.lastHash){
        state.realtime.lastHash=h;
        renderAfterLiveChange();
      }
    }).catch(function(e){console.warn("Refresco silencioso falló",e);});
  },25000);
}

function autoMigrateLegacyProcesses(){
  if(!state.cases || !state.cases.length)return;
  var migrated=[];
  state.cases.forEach(function(c){
    var changed=false;
    if(migrateLegacyCaseInMemory(c,"Migración automática de procesos legacy al cargar la app"))changed=true;
    if((currentUserIsAdminOrSuper() || normalizeRole(state.user&&state.user.role)==="gerencia") && forcePveCaseToPurchasesInMemory(c,"Migración automática V221: PVE existente debe pasar por Compras antes de Recepción"))changed=true;
    if(repairDeliveryTypeInMemory(c,"Corrección automática al cargar la app"))changed=true;
    if(repairDeliveryRouteAssignmentInMemory(c,"Normalización automática de asignación por ruta al cargar la app"))changed=true;
    if(changed)migrated.push(c);
  });
  if(!migrated.length || !db || !state.user)return;
  if(!(canSeeAll() || isAdminRoleValue(state.user.role)))return;
  migrated.forEach(function(c){
    db.collection("cases").doc(c.id).set(c,{merge:true}).catch(function(e){console.warn("No se pudo migrar proceso legacy",c.id,e);});
  });
}

function migrateLegacyProcessesNow(){
  if(!canUseAdminPanel()){alert("No tiene permiso para corregir procesos legacy.");return;}
  var migrated=[];
  state.cases.forEach(function(c){if(migrateLegacyCaseInMemory(c,"Corrección manual desde Admin"))migrated.push(c);});
  if(!migrated.length){alert("No hay casos atrapados en procesos de compromiso legacy.");renderAdmin();return;}
  Promise.all(migrated.map(function(c){return db.collection("cases").doc(c.id).set(c,{merge:true});}))
    .then(function(){alert("Procesos corregidos: "+migrated.length+". Los casos de compromiso pasaron al flujo actual.");renderAdmin();})
    .catch(function(e){showError((e&&e.message)||e||"No se pudieron corregir los procesos legacy.");});
}
function forceExistingPveToPurchasesNow(){
  if(!(currentUserIsAdminOrSuper() || normalizeRole(state.user&&state.user.role)==="gerencia")){
    alert("Solo admin, super admin o gerencia pueden forzar PVE existentes a Compras.");
    return;
  }
  if(!db){alert("No hay conexión con Firebase.");return;}
  if(!confirm("Esto enviará a Compras todos los PVE activos que aún no tengan liberación de Compras. No toca pedidos cerrados/cancelados ni PVE ya liberados. ¿Continuar?"))return;
  showLiveToast("Migrando PVE","Leyendo todos los pedidos para enviar PVE pendientes a Compras.",false);
  db.collection("cases").get().then(function(snap){
    var list=docsToList(snap), changedDocs=[], moved=0, metadataOnly=0, skipped={};
    list.forEach(function(c){
      var before=c.currentProcess+"|"+c.status+"|"+JSON.stringify(c.purchaseFlow||{})+"|"+JSON.stringify(c.visibleRoles||[])+"|"+JSON.stringify(c.documentFlow||{});
      var label=pveMigrationCandidateLabel(c);
      if(label!=="migrable_a_compras")skipped[label]=Number(skipped[label]||0)+1;
      if(forcePveCaseToPurchasesInMemory(c,"Migración manual V221: PVE existente enviado a Compras antes de Recepción")){
        var after=c.currentProcess+"|"+c.status+"|"+JSON.stringify(c.purchaseFlow||{})+"|"+JSON.stringify(c.visibleRoles||[])+"|"+JSON.stringify(c.documentFlow||{});
        if(before!==after){
          changedDocs.push(c);
          if(label==="migrable_a_compras" && c.currentProcess==="compras")moved++; else metadataOnly++;
        }
      }
    });
    if(!changedDocs.length){
      alert("No hay PVE activos pendientes por mover a Compras.\nResumen: "+JSON.stringify(skipped));
      return [];
    }
    function writeChunks(items,idx){
      idx=idx||0;
      var part=items.slice(idx,idx+25);
      if(!part.length)return Promise.resolve();
      return Promise.all(part.map(function(c){return db.collection("cases").doc(c.id).set(c,{merge:true});})).then(function(){return writeChunks(items,idx+25);});
    }
    return writeChunks(changedDocs,0).then(function(){
      state.cases=sortByUpdated(uniqueById(list));
      alert("Migración PVE terminada.\nMovidos a Compras: "+moved+"\nMarcados solo con metadata/espera segura: "+metadataOnly+"\nNo tocados: "+JSON.stringify(skipped));
      renderAdmin();
    });
  }).catch(function(e){showError("No fue possible migrar PVE existentes a Compras: "+((e&&e.message)||e));});
}

function persistCase(c,event){
  if(event){
    event=Object.assign({caseId:c.id,process:c.currentProcess,timestamp:now()},event);
    appendFlowTraceFromEvent(c,event);
  }
  c.updatedAt=now();
  return db.collection("cases").doc(c.id).set(c,{merge:true}).then(function(){
    var i=-1;for(var x=0;x<state.cases.length;x++){if(state.cases[x].id===c.id)i=x;}
    if(i>=0)state.cases[i]=c;else state.cases.unshift(c);
    if(event)return createEvent(enrichCaseEvent(c,event));
  });
}

function createEvent(e){
  e=e||{};
  e.id=e.id||uid("ev");
  e.timestamp=e.timestamp||now();
  e.userId=e.userId||(state.user?state.user.uid:"");
  e.userName=e.userName||(state.user?state.user.name:"Usuario");
  e.createdBy=e.createdBy||e.userId;
  e.createdByRole=e.createdByRole||(state.user?state.user.role:"");
  e.sourceRole=e.sourceRole||(state.user?state.user.role:"");
  e.visibleRoles=uniqueArray(e.visibleRoles||notificationVisibleRolesForEvent(null,e));
  return db.collection("case_events").doc(e.id).set(e).then(function(){state.events.unshift(e);queueEventNotification(e);});
}

function caseById(id){for(var i=0;i<state.cases.length;i++){if(state.cases[i].id===id)return state.cases[i];}return null;}
function statusChip(st){
  var map={creado_ventas:["Creado por ventas","info"],asignado:["Asignado","primary"],en_proceso:["En proceso","success"],en_espera:["En espera","warning"],espera_transportadora:["Espera transportadora","warning"],espera_ventas:["Ventas pendiente","warning"],pendiente_gerencia:["Gerencia pendiente","warning"],no_entregado:["No entregado","danger"],devolucion_caja:["Devolución a Caja","warning"],cerrado_conforme:["Cerrado conforme","success"],cerrado_con_novedad:["Cerrado con novedad","danger"],cancelado:["Cancelado","danger"]};
  var m=map[st]||[st||"Sin estado","info"];return '<span class="chip '+m[1]+'">'+esc(m[0])+'</span>';
}

function routes(){
  if(!state.user)return{main:[],processes:[]};
  var r=normalizeRole(state.user.role);
  if(currentUserIsAdminOrSuper()||currentUserIsSuperAdmin())return{main:["dashboard","create","sales_reports","projects","reception_goods","inventario","reports","cases","requirements","approvals","indicators","users","admin"],processes:activeProcessKeys()};
  if(r==="auditoria")return{main:["dashboard","sales_reports","projects","reception_goods","inventario","reports","cases","requirements","approvals","indicators","users"],processes:activeProcessKeys()};
  if(r==="auxiliar_corte")return{main:["corte_cable","cut_diag","inventario","reports"],processes:[]};
  if(r==="lider_recepcion")return{main:["dashboard","reception_goods","inventario","reports"],processes:[]};
  if(r==="proyectos")return{main:["projects","inventario","reports"],processes:[]};
  if(r==="compras")return{main:["compras","requirements","inventario","reports"],processes:[]};
  if(r==="gerencia")return{main:["indicators","approvals","inventario","reports","users","admin","dashboard"],processes:[]};
  if(isAdminRoleValue(r))return{main:["dashboard","create","sales_reports","projects","reception_goods","inventario","reports","cases","requirements","approvals","indicators","users","admin"],processes:activeProcessKeys()};
  if(r==="jefe_logistica"){
    return{main:["dashboard","cases","requirements","approvals","inventario","reports","indicators","admin"],processes:activeProcessKeys().filter(function(k){return k!=="caja";})};
  }
  var own=activeProcessKeys().filter(function(k){return canAccessProcess(r,k);});
  var routeRule=currentUserDeliveryOwnerRule();
  if(routeRule){
    own=own.filter(function(k){return !isDeliveryProcess(k) || routeRule.routes.indexOf(k)>=0;});
  }
  return{main:["dashboard"].concat(canCreate()?["create","sales_reports"]:[]).concat(canAccessProjectsModule()?["projects"]:[]).concat(["inventario","reports","requirements"]),processes:own};
}

function navBtn(r){
  var p=processes[r];var label=p?p.title:(routeInfo[r]?routeInfo[r][0]:r);var icon=p?p.icon:(routeInfo[r]?routeInfo[r][1]:"•");
  return '<button class="'+(state.route===r?'active':'')+'" data-route="'+r+'"><span class="nav-icon">'+esc(icon)+'</span><span>'+esc(label)+'</span></button>';
}

function mobileItems(){
  var r=state.user?normalizeRole(state.user.role):"";
  if(r==="auditoria")return [["dashboard","Inicio","⌂"],["cases","Casos","▤"],["reports","Nov.","RP"],["indicators","VSM","VS"]];
  if(r==="auxiliar_corte")return [["corte_cable","Cortes","CT"],["dashboard","Inicio","⌂"]];
  if(r==="lider_recepcion")return [["reception_goods","Recepción","RM"],["dashboard","Inicio","⌂"]];
  if(r==="proyectos")return [["projects","Proyectos","PR"],["dashboard","Inicio","⌂"]];
  if(r==="compras")return [["compras","Compras","CO"],["requirements","Req.","↗"],["reports","Nov.","RP"]];
  if(r==="gerencia")return [["dashboard","Inicio","⌂"],["approvals","Aprob.","✓"],["requirements","Req.","↗"]];
  if(r==="ventas")return [["create","Crear","+"],["sales_reports","Registro","RV"],["requirements","Req.","↗"],["dashboard","Inicio","⌂"]];
  if(r==="jefe_logistica")return [["dashboard","Inicio","⌂"],["cases","Casos","▤"],["requirements","Req.","↗"],["approvals","Aprob.","✓"]];
  if(isAdminRoleValue(r)||currentUserIsAdminOrSuper())return [["dashboard","Inicio","⌂"],["cases","Casos","▤"],["indicators","VSM","VS"],["admin","Admin","AD"]];
  var rs=routes();return [["dashboard","Inicio","⌂"],[rs.processes[0]||"cases","Panel","▤"],["requirements","Req.","↗"]];
}

function mobileRouteAllowed(route){
  var r=state.user?normalizeRole(state.user.role):"";
  if(currentUserIsAdminOrSuper()||currentUserIsSuperAdmin()||r==="auditoria")return true;
  var always=["dashboard","cases","requirements","approvals"];
  if(always.indexOf(route)>=0)return true;
  if(route==="compras")return r==="compras"||isAdminRoleValue(r);
  if(route==="reports")return r==="compras"||r==="ventas"||isAdminRoleValue(r)||r==="jefe_logistica"||r==="lider_recepcion";
  if(route==="create"||route==="sales_reports")return r==="ventas"||isAdminRoleValue(r);
  if(processes[route])return true;
  // Módulos de configuración, reportes extensos, usuarios, VSM, proyectos y recepción de mercancía
  // se mantienen para computador para no saturar la operación móvil.
  return false;
}

function allMobileRoutes(){
  var rs=routes();
  var items=[];
  rs.main.forEach(function(r){
    if(!mobileRouteAllowed(r))return;
    var info=routeInfo[r]||[r,"•"];
    items.push({route:r,label:info[0],icon:info[1],group:"Principal"});
  });
  rs.processes.forEach(function(r){
    if(processes[r] && mobileRouteAllowed(r))items.push({route:r,label:processes[r].title,icon:processes[r].icon,group:"Macroprocesos"});
  });
  return items;
}

function v2AllowedRoutes(rs){
  var allowed={};
  (rs.main||[]).concat(rs.processes||[]).forEach(function(r){allowed[r]=true;});
  return allowed;
}
function v2VisibleModules(rs){
  var allowed=v2AllowedRoutes(rs),mods=window.EI_V2_MODULES||[];
  return mods.filter(function(m){return (m.routes||[]).some(function(r){return allowed[r];});});
}
function v2SidebarNavigationHtml(rs){
  var allowed=Object.keys(v2AllowedRoutes(rs)),current=(window.EI_CURRENT_MODULE&&window.EI_CURRENT_MODULE.id)||"",role=(state.user&&state.user.role)||"";
  if(window.EI_NAV){window.EI_NAV.setContext({role:role,module:current,route:state.route});return window.EI_NAV.renderSidebar({role:role,currentModule:current,currentRoute:state.route,allowedRoutes:allowed});}
  return "";
}
function v2LocalRouteTabs(rs){
  var module=window.EI_CURRENT_MODULE||{},allowed=v2AllowedRoutes(rs),labels=window.EI_V2_ROUTE_LABELS||{};
  var local=(module.routes||[]).filter(function(r){return allowed[r];});
  if(local.length<2)return '<div class="v2-module-badge">'+esc(module.icon||'EI')+' · '+esc(module.title||'Módulo operativo')+'</div>';
  return '<div class="v2-module-badge">'+esc(module.icon||'EI')+' · '+esc(module.title||'Módulo operativo')+'</div><nav class="v2-local-tabs" aria-label="Secciones del módulo">'+local.map(function(r){return '<button class="'+(state.route===r?'active':'')+'" data-route="'+esc(r)+'">'+esc(labels[r]||(routeInfo[r]&&routeInfo[r][0])||(processes[r]&&processes[r].title)||r)+'</button>';}).join('')+'</nav>';
}
function mobileFullMenuHtml(){
  var rs=routes(),current=(window.EI_CURRENT_MODULE&&window.EI_CURRENT_MODULE.id)||"",role=(state.user&&state.user.role)||"",allowed=Object.keys(v2AllowedRoutes(rs));
  var navigation=window.EI_NAV?window.EI_NAV.renderMobile({role:role,currentModule:current,currentRoute:state.route,allowedRoutes:allowed}):"";
  return '<section class="mobile-menu-panel clean ei193-menu-popup"><div class="mobile-menu-head clean"><div><strong>Procesos y módulos</strong><span>Acceso organizado según su rol</span></div><button class="mobile-close-btn" data-action="closeMobileMenu" aria-label="Cerrar menú">×</button></div>'+navigation+'<div class="mobile-menu-group mobile-session-box"><h3>Sesión</h3><div class="mobile-user-pill"><strong>'+esc((state.user&&state.user.name)||"Usuario")+'</strong><small>'+esc((state.user&&state.user.email)||roleTitle(state.user&&state.user.role))+'</small></div><button class="btn btn-danger" data-action="logout">Cerrar sesión</button></div></section>';
}
function loadWarningsHtml(){
  if(!state.loadWarnings || !state.loadWarnings.length)return "";
  return '<div class="alert warning"><strong>Algunas consultas no respondieron correctamente.</strong><br>'+esc(state.loadWarnings.slice(0,3).join(" | "))+'<br><small>Puede tratarse de conexión, sesión o permisos. La aplicación conserva la información ya cargada.</small></div>';
}


