function cutGroupKey(cut){return normalizeRefText(cut.referencia||cut.descripcion||"SIN_REFERENCIA")||"SIN_REFERENCIA";}
function cutGroupTitle(cut){return (cut.referencia||"Sin referencia")+(cut.descripcion?" · "+cut.descripcion:"");}
function cutPendingStatus(cut){return !cutIsOperationallyDone(cut);}
function renderCutsQueue(){
  cleanupProtectedToast();
  var rows=[];
  state.cases.forEach(function(c){(c.cutRequests||[]).forEach(function(cut){if(!cutPendingStatus(cut))return;rows.push({c:c,cut:cut});});});
  var groups={};
  rows.forEach(function(r){
    var k=cutGroupKey(r.cut);
    if(!groups[k])groups[k]={key:k,title:cutGroupTitle(r.cut),items:[],meters:0};
    groups[k].items.push(r);
    var m=cutParseDecimal(r.cut.metrosSolicitados||r.cut.metrajeFinal);
    if(Number.isFinite(m))groups[k].meters+=m;
  });

  if(isMobileRuntime()||isCutRuntimeUser()){
    var groupKeys=Object.keys(groups).sort(function(a,b){return groups[b].meters-groups[a].meters || groups[a].title.localeCompare(groups[b].title);});
    var groupHtml=groupKeys.map(function(k){
      var g=groups[k];
      var items=g.items.map(function(r){
        return '<article class="ei191-cut-item">'+
          '<div class="ei191-cut-item-top">'+
            '<div class="ei191-order"><strong>'+esc(r.c.reference||r.cut.pedido||"")+'</strong><small>'+esc(r.c.client||"")+'</small></div>'+
            '<div class="ei191-status">'+v239CutStatusChip(r.cut)+'</div>'+
          '</div>'+
          '<div class="ei191-cut-item-metrics">'+
            '<div><span>Código corte</span><b>'+esc(r.cut.code||r.cut.id||"")+'</b></div>'+
            '<div><span>Metros a cortar</span><b>'+esc(r.cut.metrosSolicitados||r.cut.metrajeFinal||"")+' m</b></div>'+
          '</div>'+
          '<div class="ei191-cut-item-ref"><span>Referencia</span><strong>'+esc(r.cut.referencia||"")+'</strong><p>'+esc(r.cut.descripcion||"")+'</p>'+v239UnavailableNoteHtml(r.cut)+'</div>'+
          '<div class="v239-cut-actions"><button class="btn btn-primary" data-action="'+(v239IsCutUnavailable(r.cut)?"resumeUnavailableCut":"launchCut")+'" data-id="'+esc(r.c.id)+'" data-cut="'+esc(r.cut.id)+'">'+(v239IsCutUnavailable(r.cut)?"Retomar corte":"Abrir corte")+'</button><button class="btn btn-danger" data-action="cutUnavailable" data-id="'+esc(r.c.id)+'" data-cut="'+esc(r.cut.id)+'">'+(v239IsCutUnavailable(r.cut)?"Actualizar novedad":"Corte no disponible")+'</button></div>'+
        '</article>';
      }).join("");
      return '<details class="ei191-cut-group" open>'+
        '<summary><div class="ei191-group-title"><strong>'+esc(g.title)+'</strong><small>'+g.items.length+' corte(s) pendiente(s)</small></div><aside><b>'+esc(cutNormalizeDecimal(g.meters))+' m</b><span>prealistamiento</span></aside></summary>'+
        '<div class="ei191-prep"><strong>Prealistamiento:</strong> reúna este cable por referencia y opere todos los tramos consecutivamente desde el mismo rollo.<button class="btn btn-success" style="margin-top:9px;width:100%" data-action="startReferenceCuts" data-ref="'+esc(g.key)+'">Iniciar cortes por referencia</button></div>'+
        '<section class="ei191-cut-items">'+items+'</section>'+
      '</details>';
    }).join("");
    layout(
      header("Cortes agrupados","Bandeja organizada por referencia/tipo de cable para prealistamiento y operación por pedido.",'<button class="btn btn-success" data-action="forceProtectedRefresh">Actualizar bandeja</button><button class="btn btn-gold" data-action="v254Send4582Billing" data-ref="4582">Pasar 4582 a Facturación</button>')+
      '<section class="ei191-cut-kpis"><article><span>Pendientes</span><strong>'+rows.length+'</strong></article><article><span>Grupos</span><strong>'+groupKeys.length+'</strong></article><article><span>Versión</span><strong>V254</strong></article></section>'+
      '<section class="ei191-cut-groups">'+(groupHtml||'<section class="card"><div class="empty">No hay cortes pendientes.</div></section>')+'</section>'
    );
    return;
  }

  var groupHtml=Object.keys(groups).sort(function(a,b){return groups[b].meters-groups[a].meters;}).map(function(k){
    var g=groups[k];
    var body=g.items.map(function(r){return '<tr><td>'+esc(r.c.reference||r.cut.pedido||'')+'</td><td>'+esc(r.c.client||'')+'</td><td>'+pdfMiniButton(r.c)+'</td><td>'+esc(r.cut.code||r.cut.id)+'</td><td>'+esc(r.cut.metrosSolicitados||'')+'</td><td>'+v239CutStatusChip(r.cut)+'</td><td><div class="v239-cut-actions"><button class="btn btn-small btn-primary" data-action="'+(v239IsCutUnavailable(r.cut)?'resumeUnavailableCut':'launchCut')+'" data-id="'+esc(r.c.id)+'" data-cut="'+esc(r.cut.id)+'">'+(v239IsCutUnavailable(r.cut)?'Retomar corte':'Abrir corte')+'</button><button class="btn btn-small btn-danger" data-action="cutUnavailable" data-id="'+esc(r.c.id)+'" data-cut="'+esc(r.cut.id)+'">'+(v239IsCutUnavailable(r.cut)?'Actualizar novedad':'Corte no disponible')+'</button></div>'+v239UnavailableNoteHtml(r.cut)+'</td></tr>';}).join('');
    return '<details class="card cut-group" open><summary><div><strong>'+esc(g.title)+'</strong><small>'+g.items.length+' corte(s) pendiente(s) · Prealistamiento sugerido: '+esc(cutNormalizeDecimal(g.meters))+' m</small></div><span class="chip primary">'+esc(g.key)+'</span></summary><div class="notice"><strong>Prealistamiento:</strong> reúna el cable por esta referencia y opere los cortes en secuencia desde un mismo rollo.<div class="top-actions" style="margin-top:10px"><button class="btn btn-success" data-action="startReferenceCuts" data-ref="'+esc(g.key)+'">Iniciar cortes por referencia</button></div></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>PDF</th><th>Corte</th><th>Metros</th><th>Estado</th><th>Acción</th></tr></thead><tbody>'+body+'</tbody></table></div></details>';
  }).join('');
  layout(header("Cortes de cable","Bandeja agrupada por tipo de cable para prealistamiento eficiente. Las solicitudes llegan durante el día, se consolidan por referencia y luego se operan pedido por pedido.",'<button class="btn btn-primary" data-action="exportCutsExcel">Excel dashboard cortes</button><button class="btn btn-success" data-action="forceProtectedRefresh">Actualizar vista</button><button class="btn btn-gold" data-action="v254Send4582Billing" data-ref="4582">Pasar 4582 a Facturación</button>')+'<section class="grid grid-3"><article class="card kpi"><span>Cortes pendientes</span><strong>'+rows.length+'</strong><small>Pedidos por cortar</small></article><article class="card kpi"><span>Tipos de cable</span><strong>'+Object.keys(groups).length+'</strong><small>Agrupados</small></article><article class="card kpi"><span>Funcionalidad</span><strong>Completa</strong><small>Misma lógica de PC</small></article></section><section style="margin-top:16px">'+(groupHtml||'<section class="card"><div class="empty">No hay cortes pendientes.</div></section>')+'</section>');
}

function requirementIsPending(req){
  if(!req)return false;
  var s=normalizePersonComparableText(req.status||"pendiente");
  return !(s==="resuelto"||s==="cerrado"||s==="cancelado"||s==="gestionado"||s==="finalizado"||s==="cerrado_solucionado");
}
function pendingRequirements(c){
  return (c&&c.requirements||[]).filter(requirementIsPending);
}
function pendingSalesRequirements(c){
  return pendingRequirements(c).filter(function(req){return normalizeRole(req.targetRole)==="ventas";});
}
function reportStatusReleasesSales(status){
  var s=normalizePersonComparableText(status||"");
  return s==="gestionado"||s==="cerrado"||s==="resuelto"||s==="finalizado"||s==="cerrado_solucionado"||s==="respondido";
}
function reportIsClosedOrAnswered(r){
  if(!r)return false;
  if(reportStatusReleasesSales(r.status)||reportStatusReleasesSales(r.finalStatus)||reportStatusReleasesSales(r.salesResponseStatus))return true;
  if(r.closedAt||r.finalizedAt||r.managedAt||r.salesResponseAt)return true;
  var txt=normalizePersonComparableText([r.status,r.finalStatus,r.lastUpdateType,r.closureComment].join(" "));
  return /cerrado|gestionado|resuelto|finalizado|respondido|solucionado/.test(txt);
}
function salesRequirementResolvedSignal(req){
  if(!req)return false;
  if(!requirementIsPending(req))return true;
  if(req.answeredAt||req.closedAt||req.answer)return true;
  return reportStatusReleasesSales(req.status);
}
function caseHasSalesResolutionSignal(c){
  if(!c)return false;
  if(caseIsPvc4549Sogamoso(c))return true;
  if((c.requirements||[]).some(function(req){return normalizeRole(req.targetRole)==="ventas" && salesRequirementResolvedSignal(req);}))return true;
  if(c.openRequirement && normalizeRole(c.openRequirement.targetRole)==="ventas" && salesRequirementResolvedSignal(c.openRequirement))return true;
  return (state.reports||[]).some(function(r){return reportBelongsToCase(r,c)&&reportIsClosedOrAnswered(r);});
}
function caseIsPvc4549Sogamoso(c){
  if(!c)return false;
  var t=normalizePersonComparableText([caseDisplayTitle(c),caseBaseReference(c),purchaseOrderValue(c),c.client,c.reference,c.pedido,c.caseNumber,c.orderNumber].join(" "));
  return t.indexOf("pvc 4549")>=0 && (t.indexOf("11700024")>=0 || t.indexOf("sogamoso")>=0);
}
function releaseAnyCaseIfResolvedByReqOrReport(c,detail,origin){
  if(!c||!caseLooksBlockedInSales(c))return false;
  if(!caseHasSalesResolutionSignal(c))return false;
  return releaseCaseFromSalesBlock(c,detail||"Requerimiento o novedad/reporte ya respondido/cerrado.",origin||"Liberación por respuesta/cierre");
}
function forceReleaseOneSalesBlock(id){
  var c=caseById(id);if(!c)return;
  if(!canForceReleaseSalesBlocks()){alert("No tiene permiso para liberar bloqueos de Ventas.");return;}
  if(!caseLooksBlockedInSales(c)){alert("Este pedido no aparece bloqueado en Ventas.");return;}
  if(!caseHasSalesResolutionSignal(c) && !confirm("No encontré respuesta/cierre asociado, ¿desea liberarlo manualmente de todas formas?"))return;
  if(!releaseCaseFromSalesBlock(c,"Liberación manual V221 por rol autorizado.","Liberación manual V221")){alert("No fue posible liberar este pedido.");return;}
  persistCase(c,{type:"SALES_BLOCK_MANUAL_RELEASED",detail:"Liberación manual V221: pedido devuelto a "+processTitle(c.currentProcess),targetRole:c.assignedRole,visibleRoles:["admin","super_admin","super_administrador","gerencia","jefe_logistica",c.assignedRole,"ventas"]}).then(loadData).then(function(){renderDetail(id);alert("Pedido liberado de Ventas y devuelto a "+processTitle(c.currentProcess)+".");}).catch(function(e){showError((e&&e.message)||e||"No se pudo liberar el pedido.");});
}
function caseLooksBlockedInSales(c){
  if(!c)return false;
  return c.status==="espera_ventas" || normalizeRole(c.assignedRole)==="ventas" || (c.openRequirement&&normalizeRole(c.openRequirement.targetRole)==="ventas") || (c.salesHold&&c.salesHold.status&&String(c.salesHold.status).toUpperCase().indexOf("ESPERA_VENTAS")>=0);
}
function salesReturnProcess(c){
  var req=c&&c.openRequirement||null;
  if(req&&req.returnProcess)return req.returnProcess;
  var list=(c&&c.requirements||[]).slice().reverse();
  for(var i=0;i<list.length;i++){
    if(normalizeRole(list[i].targetRole)==="ventas" && (list[i].returnProcess||list[i].sourceProcess))return list[i].returnProcess||list[i].sourceProcess;
  }
  if(c&&c.salesHold&&String(c.salesHold.status||"").toUpperCase().indexOf("SEPARACION")>=0)return "caja";
  if(c&&c.currentProcess&&c.currentProcess!=="ventas")return c.currentProcess;
  return "recepcion_pedidos";
}
function clearCasePersonalAssignment(c,next){
  c.assignedTo="";c.assignedUid="";c.assignedEmail="";c.assignedUsers=[];c.assignedUserIds=[];
  c.assignedRole=primaryOwnerRole(next);c.assignedName=processOwnerTitle(next);
}
function closeSalesBlockMarkers(c,detail){
  var stamp=now();
  (c.requirements||[]).forEach(function(req){
    if(normalizeRole(req.targetRole)==="ventas" && requirementIsPending(req)){
      req.status="resuelto";req.answeredAt=req.answeredAt||stamp;req.answeredBy=req.answeredBy||(state.user?state.user.uid:"");req.answeredByName=req.answeredByName||(state.user?state.user.name:"");req.answer=req.answer||detail||"Gestión resuelta por Ventas.";
    }
  });
  if(c.openRequirement&&normalizeRole(c.openRequirement.targetRole)==="ventas"){
    c.openRequirement.status="resuelto";
    c.openRequirement.answeredAt=stamp;
    c.openRequirement.answer=detail||"Gestión resuelta por Ventas.";
  }
  if(c.salesHold&&String(c.salesHold.status||"").toUpperCase().indexOf("ESPERA_VENTAS")>=0){
    c.salesHold.history=c.salesHold.history||[];
    c.salesHold.history.push({at:stamp,by:state.user?state.user.name:"Sistema",action:"ventas_resuelve_y_libera",detail:detail||""});
    c.salesHold.status="VENTAS_RESPONDIO";
    c.salesHold.salesResolvedAt=stamp;
    c.salesHold.salesResolvedByName=state.user?state.user.name:"";
    c.salesHold.salesResolutionDetail=detail||"";
  }
}
function releaseCaseFromSalesBlock(c,detail,origin){
  if(!c||!caseLooksBlockedInSales(c))return false;
  var ret=salesReturnProcess(c);
  if(!processes[ret])ret="recepcion_pedidos";
  stopWait(c);
  closeSalesBlockMarkers(c,detail);
  var stamp=now();
  c.currentProcess=ret;
  c.status="asignado";
  c.openRequirement=null;
  c.waitStartedAt=null;
  c.activeStartedAt=null;
  c.deadStartedAt=stamp;
  c.closedAt=null;
  clearCasePersonalAssignment(c,ret);
  var ps=procStats(c,ret);ps.startedAt=ps.startedAt||stamp;ps.handoffs=Number(ps.handoffs||0)+1;
  addStateHistory(c,"liberacion_ventas",(origin||"Ventas resolvió bloqueo")+" · vuelve a "+processTitle(ret)+(detail?": "+detail:""),{tipo_estado:"liberacion_ventas",fromProcess:"ventas",toProcess:ret,fecha_hora_inicio_estado:stamp,motivo_novedad:detail||""});
  return true;
}
function linkedCaseForReport(r){
  if(!r)return null;
  var ids=reportCaseIdentifiers(r);
  for(var i=0;i<ids.length;i++){var c=caseById(ids[i]);if(c)return c;}
  for(var x=0;x<(state.cases||[]).length;x++){if(reportBelongsToCase(r,state.cases[x]))return state.cases[x];}
  return null;
}
function releaseCaseFromResolvedSalesReport(r,status,comment){
  if(!reportStatusReleasesSales(status) && !reportIsClosedOrAnswered(Object.assign({},r,{status:status})))return Promise.resolve(false);
  var c=linkedCaseForReport(r);
  if(!c)return Promise.resolve(false);
  if(!releaseCaseFromSalesBlock(c,comment,"Novedad/reporte cerrado o gestionado"))return Promise.resolve(false);
  return persistCase(c,{type:"SALES_BLOCK_RELEASED_BY_REPORT",detail:"Novedad/reporte cerrado/gestionado: "+(comment||""),targetRole:c.assignedRole,visibleRoles:["admin","super_admin","super_administrador","gerencia","jefe_logistica",c.assignedRole,"ventas"]}).then(function(){return true;});
}
function canForceReleaseSalesBlocks(){
  return state.user && !currentUserIsAuditReadOnly() && (canSeeAll() || canManageReports() || currentUserIsAdminOrSuper());
}
function forceReleaseResolvedSalesBlocksNow(){
  if(!canForceReleaseSalesBlocks()){alert("No tiene permiso para liberar bloqueos de Ventas.");return;}
  var changed=[],promises=[];
  (state.cases||[]).forEach(function(c){
    if(!caseLooksBlockedInSales(c))return;
    if(!caseHasSalesResolutionSignal(c))return;
    if(releaseCaseFromSalesBlock(c,"Reparación V221: requerimiento o novedad/reporte respondido/cerrado. Incluye liberación aunque exista requerimiento y reporte al mismo tiempo.","Reparación V221")){
      changed.push(c);
      promises.push(persistCase(c,{type:"SALES_BLOCK_FORCE_RELEASED_V221",detail:"Reparación V221: pedido liberado de Ventas y devuelto a "+processTitle(c.currentProcess),targetRole:c.assignedRole,visibleRoles:["admin","super_admin","super_administrador","gerencia","jefe_logistica",c.assignedRole,"ventas"]}));
    }
  });
  if(!changed.length){alert("No se encontraron pedidos con requerimiento/novedad ya respondida o cerrada para liberar de Ventas.");return;}
  Promise.all(promises).then(loadData).then(function(){renderCases();alert("Listo. Se liberaron "+changed.length+" pedido(s) de Ventas. Si estaba el PVC 4549 · OC 11700024 SOGAMOSO, ya quedó devuelto al flujo normal.");}).catch(function(e){showError((e&&e.message)||e||"No se pudo liberar bloqueos de Ventas.");});
}
function isRequirementVisibleForUser(c){
  if(!state.user || !c)return false;
  var unresolved=pendingRequirements(c);
  var activeReq=(c.status==="espera_ventas"||c.status==="en_espera"||c.status==="no_entregado"||c.status==="devolucion_caja"||!!c.openRequirement||unresolved.length>0);
  if(!activeReq)return false;
  if(userIsGlobalVisibilityRole())return !!activeReq;
  if(c.openRequirement && requirementTargetsCurrentArea(c,c.openRequirement))return true;
  return unresolved.some(function(req){return requirementTargetsCurrentArea(c,req);});
}
function visibleRequirements(){
  return filterCasesForCurrentUserStrict(state.cases||[]).filter(isRequirementVisibleForUser).sort(function(a,b){return new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt);});
}
function renderRequirements(){
  var title=state.user&&normalizeRole(state.user.role)==="ventas"?"Requerimientos de Ventas":"Requerimientos";
  var subtitle=state.user&&normalizeRole(state.user.role)==="ventas"?"Solicitudes enviadas a Ventas sobre pedidos propios o asignados.":"Solo se muestran requerimientos asignados a su área, proceso o usuario.";
  layout(header(title,subtitle)+caseList(visibleRequirements()));
}
function cutApprovalsForRole(){
  var role=state.user?state.user.role:"";
  var nr=normalizeRole(role);
  var rows=[];
  state.cases.forEach(function(c){
    (c.cutRequests||[]).forEach(function(cut){
      var pending=cut.approvalStatus==="PENDIENTE" || cut.status==="PENDIENTE_GERENCIA" || cut.status==="PENDIENTE_JEFE_LOGISTICA" || cut.status==="PENDIENTE_LIDER";
      if(!pending)return;
      var rule=cutRule(cut.tipoPedido||"VENTAS",cutParseDecimal(cut.remanenteProyectado));
      if(nr==="admin" || nr==="super_admin" || userCanApproveCut(rule,cut) || normalizeRole(cut.approverRole)===nr || normalizeRole(c.assignedRole)===nr)rows.push({caseObj:c,cut:cut});
    });
  });
  return rows;
}
function renderApprovals(){
  var cutRows=cutApprovalsForRole();
  var title="Aprobaciones";
  var subtitle="Aprobaciones de remanente, prioridades y requerimientos críticos.";
  var cutHtml=cutRows.length?'<section class="card" style="margin-bottom:16px"><h3>Aprobaciones de corte</h3><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Corte</th><th>Referencia</th><th>Sobrante</th><th>Solicita</th><th>Acción</th></tr></thead><tbody>'+cutRows.map(function(r){return '<tr><td>'+esc(r.caseObj.reference||"")+'</td><td>'+esc(r.caseObj.client||"")+'</td><td>'+esc(r.cut.code||r.cut.id)+'</td><td>'+esc(r.cut.referencia||"")+'</td><td>'+esc(r.cut.remanenteProyectado||"")+'</td><td>'+esc(r.cut.approverLabel||roleTitle(r.cut.approverRole))+'</td><td><button class="btn btn-small btn-primary" data-action="launchCut" data-id="'+esc(r.caseObj.id)+'" data-cut="'+esc(r.cut.id)+'">Revisar</button></td></tr>';}).join('')+'</tbody></table></div></section>':'';
  var list;
  if(state.user && normalizeRole(state.user.role)==="jefe_logistica"){
    title="Aprobaciones logísticas";
    subtitle="Validaciones de corte igual a 50 m, excepciones y casos detenidos.";
    list=state.cases.filter(function(c){return !c.closedAt && (c.assignedRole==="jefe_logistica" || (c.openRequirement && c.openRequirement.targetRole==="jefe_logistica") || c.priority==="Alta" || c.status==="en_espera" || c.status==="espera_ventas");});
  }else{
    list=state.cases.filter(function(c){return c.status==="pendiente_gerencia";});
  }
  layout(header(title,subtitle)+cutHtml+caseList(list));
}


function bars(items){
  items=(items||[]).filter(function(x){return x&&Number.isFinite(Number(x.value||0));});
  if(!items.length)return '<div class="empty" style="padding:12px">Sin datos suficientes para graficar.</div>';
  var max=items.reduce(function(m,x){return Math.max(m,Number(x.value||0));},0)||1;
  return '<div class="bars">'+items.map(function(x){
    var val=Number(x.value||0);
    var w=clamp((val/max)*100,0,100);
    return '<div class="bar-row"><span>'+esc(x.label||'Sin etiqueta')+'</span><div><b style="width:'+w.toFixed(1)+'%"></b></div><small>'+fmt(val)+'</small></div>';
  }).join('')+'</div>';
}

function countBars(items){
  items=(items||[]).filter(function(x){return x&&Number.isFinite(Number(x.value||0));});
  if(!items.length)return '<div class="empty" style="padding:12px">Sin datos suficientes para graficar.</div>';
  var max=items.reduce(function(m,x){return Math.max(m,Number(x.value||0));},0)||1;
  return '<div class="bars">'+items.map(function(x){
    var val=Number(x.value||0);
    var w=clamp((val/max)*100,0,100);
    return '<div class="bar-row"><span>'+esc(x.label||'Sin etiqueta')+'</span><div><b style="width:'+w.toFixed(1)+'%"></b></div><small>'+val+'</small></div>';
  }).join('')+'</div>';
}


function miniBarsHtml(items){
  return countBars(items||[]);
}

function modal(title,body){
  return '<section class="modal"><div class="modal-head"><div><h3>'+esc(title||'Detalle')+'</h3></div><button class="btn btn-small" type="button" data-action="closeDrawer">Cerrar</button></div>'+(body||'')+'</section>';
}


function ensureV221CutUiFixes(){
  if(document.getElementById('ei-v221-cargues-movil-galeria-archivos-10'))return;
  var st=document.createElement('style');st.id='ei-v221-cargues-movil-galeria-archivos-10';
  st.textContent='.cut-simple-head{gap:10px}.cut-quick-note{font-size:.95rem}.cut-full fieldset{margin-top:12px;padding:14px;border-radius:18px}.cut-full legend{font-weight:900;color:#061b46}.cut-full .top-actions{gap:8px;flex-wrap:wrap}.cut-full .top-actions .btn{min-height:42px}.cut-full .btn[data-cut-action="noCutNeeded"]{font-weight:900}.cut-timer-card{padding:12px}.compact-lines-table td,.compact-lines-table th{vertical-align:top}.drawer .modal{max-width:min(1040px,96vw)}@media(max-width:720px){.drawer .modal{width:96vw;max-height:94vh;border-radius:22px}.modal-head{position:sticky;top:0;z-index:3;background:#fff}.cut-full fieldset{padding:12px}.cut-full .top-actions{display:grid;grid-template-columns:1fr;gap:8px}.cut-full .top-actions .btn{width:100%;justify-content:center}.cut-grid,.cut-grid-2,.cut-grid-3,.cut-grid-4{grid-template-columns:1fr!important}.cut-simple-head{grid-template-columns:1fr!important}.cut-timer{font-size:1.5rem}}';
  document.head.appendChild(st);
}

function drawer(html){
  ensureV221UiFixes();
  ensureV221CutUiFixes();
  var d=qs('#drawer');
  if(!d){d=document.createElement('div');d.id='drawer';d.className='drawer';document.body.appendChild(d);}
  d.innerHTML=html||'';
  d.classList.add('open');
  qsa('[data-action="closeDrawer"]',d).forEach(function(btn){btn.onclick=function(ev){ev.preventDefault();closeDrawer();};});
  try{bindActions();}catch(e){novaCaptureError(e,"operación heredada");}
  d.onclick=function(ev){if(ev.target===d)closeDrawer();};
}

function closeDrawer(){
  var d=qs('#drawer');
  if(!d)return;
  d.classList.remove('open');
  window.setTimeout(function(){if(!d.classList.contains('open'))d.innerHTML='';},120);
}

function renderUsers(){
  if(!canManageUsers() && !canAuditViewAll()){layout(header("Usuarios","Acceso restringido.")+'<div class="empty">Solo admin, gerencia o auditoría pueden consultar este módulo.</div>');return;}
  var ger=state.users.filter(function(u){return normalizeRole(u.role)==="gerencia" && u.isActive!==false;}).length;
  var active=state.users.filter(function(u){return u.isActive!==false;}).length;
  var rows=state.users.map(function(u){
    var self=state.user && u.id===state.user.uid;
    return '<tr><td><strong>'+esc(u.name||'Sin nombre')+'</strong>'+(self?'<br><small>Sesión actual</small>':'')+'</td><td>'+esc(u.email||'')+'</td><td>'+esc(roleTitle(u.role))+'</td><td>'+(u.isActive===false?'<span class="chip danger">Inactivo</span>':'<span class="chip success">Activo</span>')+'</td><td>'+(canManageUsers()?'<div class="top-actions"><button class="btn btn-small" data-action="editUserRole" data-id="'+esc(u.id)+'">Rol</button><button class="btn btn-small btn-gold" data-action="toggleUserActive" data-id="'+esc(u.id)+'">'+(u.isActive===false?'Activar':'Inactivar')+'</button>'+((self||!isAdminRoleValue(state.user.role))?'':'<button class="btn btn-small btn-danger" data-action="deleteUserProfile" data-id="'+esc(u.id)+'">Eliminar</button>')+'</div>':'<span class="chip info">Solo lectura</span>')+'</td></tr>';
  }).join('');
  layout(header("Usuarios",canAuditViewAll()?"Directorio de usuarios en modo auditoría solo lectura.":"Gestión completa de perfiles: crear usuarios, cambiar roles, activar/inactivar y eliminar perfiles operativos.",canManageUsers()?'<button class="btn btn-primary" data-action="userModal">Crear usuario</button>':"")+auditReadOnlyNotice()+'<section class="grid grid-3"><article class="card kpi"><span>Usuarios activos</span><strong>'+active+'</strong><small>'+state.users.length+' perfiles cargados</small></article><article class="card kpi"><span>Gerencia</span><strong>'+ger+'/2</strong><small>Límite operativo</small></article><article class="card kpi"><span>Roles</span><strong>'+uniqueRoles()+'</strong><small>Incluye líder recepción</small></article></section><section class="card" style="margin-top:16px"><div class="notice"><strong>Control administrativo:</strong> El botón eliminar borra el perfil de Firestore y bloquea el acceso operativo. Para eliminar también la cuenta de Firebase Authentication se requiere hacerlo desde Firebase Console o una Cloud Function segura.</div><h3>Directorio</h3><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>'+(rows||'<tr><td colspan="5">No hay usuarios cargados.</td></tr>')+'</tbody></table></div></section>');
}
function uniqueRoles(){var m={};state.users.forEach(function(u){if(u&&u.role)m[normalizeRole(u.role)]=1;});return Object.keys(m).length;}
function roleOptionsHtml(selected){return Object.keys(roles).filter(function(r){return r!=="lider_logistico";}).map(function(r){return '<option value="'+esc(r)+'" '+(normalizeRole(selected)===normalizeRole(r)?'selected':'')+'>'+esc(roles[r])+'</option>';}).join('');}
function openEditUserRole(id){
  if(!canManageUsers())return;
  var u=state.users.filter(function(x){return x.id===id;})[0];if(!u){alert("Usuario no encontrado.");return;}
  drawer(modal("Cambiar rol / estado",'<form class="form" id="editUserRoleForm"><div class="notice"><strong>'+esc(u.name||u.email||'Usuario')+'</strong><br>'+esc(u.email||'')+'</div><label class="field"><span>Rol operativo</span><select class="select" name="role">'+roleOptionsHtml(u.role)+'</select></label><label class="check-card"><input type="checkbox" name="isActive" '+(u.isActive===false?'':'checked')+'> Usuario activo en el aplicativo</label><label class="field"><span>Observación administrativa</span><textarea class="textarea" name="note" placeholder="Cambio solicitado, ajuste de funciones o retiro temporal."></textarea></label><button class="btn btn-primary" type="submit">Guardar cambios</button></form>'));
  qs("#editUserRoleForm").onsubmit=function(e){e.preventDefault();var fd=new FormData(e.target);updateUserProfile(id,{role:fd.get("role"),isActive:!!fd.get("isActive"),note:fd.get("note")||""});};
}
function updateUserProfile(id,data){
  if(!canManageUsers())return;
  if(id===state.user.uid && data.isActive===false){alert("No puede inactivar su propio usuario en sesión.");return;}
  var payload={role:data.role,isActive:!!data.isActive,updatedAt:now(),updatedBy:state.user.uid};
  db.collection("users").doc(id).update(payload).then(function(){return createEvent({type:"USER_ROLE_UPDATED",detail:"Usuario actualizado: "+id+" · "+roleTitle(data.role)+(data.note?" · "+data.note:""),targetRole:"admin",visibleRoles:["admin","super_admin","super_administrador","gerencia"]}).catch(function(){return null;});}).then(loadData).then(function(){closeDrawer();renderUsers();}).catch(function(e){showError(e.message||e);});
}
function toggleUserActive(id){
  var u=state.users.filter(function(x){return x.id===id;})[0];if(!u)return;
  if(id===state.user.uid){alert("No puede inactivar su propio usuario.");return;}
  updateUserProfile(id,{role:u.role,isActive:u.isActive===false,note:"Cambio rápido de estado"});
}
function deleteUserProfile(id){
  if(!isAdminRoleValue(state.user.role)){alert("Solo Super Admin / Admin puede eliminar usuarios.");return;}
  if(id===state.user.uid){alert("No puede eliminar su propio usuario en sesión.");return;}
  var u=state.users.filter(function(x){return x.id===id;})[0];if(!u){alert("Usuario no encontrado.");return;}
  if(!confirm("¿Eliminar el perfil operativo de "+(u.name||u.email||id)+"? Esta acción impide el acceso al aplicativo."))return;
  db.collection("users_deleted_log").doc(id+"_"+Date.now()).set({userId:id,name:u.name||"",email:u.email||"",role:u.role||"",deletedAt:now(),deletedBy:state.user.uid,deletedByName:state.user.name||""}).catch(function(){return null;}).then(function(){return db.collection("users").doc(id).delete();}).then(function(){return createEvent({type:"USER_PROFILE_DELETED",detail:"Perfil operativo eliminado: "+(u.name||u.email||id),targetRole:"admin",visibleRoles:["admin","super_admin","super_administrador","gerencia"]}).catch(function(){return null;});}).then(loadData).then(function(){renderUsers();}).catch(function(e){showError(e.message||e);});
}

function renderProjectOrders(){
  if(!canAccessProjectsModule()){layout(header("Proyectos","Acceso restringido.")+'<div class="empty">Este módulo está disponible únicamente para el rol Proyectos y Super Admin/Admin.</div>');return;}
  var enabled=isProjectUploadDay();
  var rows=(state.projectOrders||[]).map(function(p){
    var tipo=p.requestType||"Pedido";
    var entrega=p.pickupPoint?"Recoge en punto":(p.deliveryType==="obra"?"Entrega en obra/proyecto":"Despacho / entrega");
    return '<tr><td><strong>'+esc(p.projectName||'Proyecto')+'</strong><br><small>'+esc(p.customer||'')+'</small></td><td><strong>'+esc(tipo)+'</strong><br><small>'+esc(p.orderRef||'')+'</small></td><td>'+esc(p.requiredDate||'Sin fecha')+'</td><td>'+esc(entrega)+'</td><td>'+esc(p.status||'Creado')+'</td><td>'+fmtDate(p.createdAt)+'</td><td><button class="btn btn-small" data-action="projectToCase" data-id="'+esc(p.id)+'">Enviar a flujo</button></td></tr>';
  }).join('');
  layout(header("Pedidos de proyectos","Módulo exclusivo para que Proyectos registre PNF y pedidos de proyectos, con fecha requerida y trazabilidad hacia logística.",(enabled?'<button class="btn btn-primary" data-action="projectOrderModal">Crear pedido / PNF</button>':'<button class="btn" disabled>'+projectUploadDayText()+'</button>'))+'<section class="grid grid-3"><article class="card kpi"><span>Disponibilidad</span><strong>'+esc(enabled?'Abierto':'Cerrado')+'</strong><small>Lunes y jueves</small></article><article class="card kpi"><span>Solicitudes</span><strong>'+((state.projectOrders||[]).length)+'</strong><small>PNF y pedidos registrados</small></article><article class="card kpi"><span>Control</span><strong>Proyectos</strong><small>Acceso exclusivo por rol</small></article></section><section class="card" style="margin-top:16px"><div class="notice"><strong>Regla del módulo:</strong> solo el rol Proyectos y Super Admin/Admin pueden ingresar. El formulario exige indicar para qué día se necesita el pedido o PNF.</div><h3>Bandeja de proyectos</h3><div class="table-wrap"><table><thead><tr><th>Proyecto / cliente</th><th>Tipo / pedido</th><th>Fecha requerida</th><th>Entrega</th><th>Estado</th><th>Creación</th><th>Acción</th></tr></thead><tbody>'+(rows||'<tr><td colspan="7">Sin pedidos de proyectos registrados.</td></tr>')+'</tbody></table></div></section>');
}
function openProjectOrderModal(){
  if(!canAccessProjectsModule()){alert("No tiene permiso para crear pedidos de proyecto.");return;}
  if(!isProjectUploadDay()){alert("El módulo de proyectos solo permite cargar pedidos los lunes y jueves.");return;}
  var today=new Date().toISOString().slice(0,10);
  drawer(modal("Crear pedido / PNF de proyecto",'<form class="form" id="projectOrderForm"><div class="notice"><strong>Pedido de proyecto:</strong> registre PNF, pedido o ambos. Este flujo queda separado de Ventas y entra a logística como solicitud de Proyectos.</div><div class="grid grid-2"><label class="field"><span>Tipo de solicitud *</span><select class="select" name="requestType" required><option value="PNF">PNF</option><option value="Pedido">Pedido</option><option value="PNF y pedido">PNF y pedido</option></select></label><label class="field"><span>Para qué día lo necesitan *</span><input class="input" type="date" name="requiredDate" min="'+today+'" required></label></div><div class="grid grid-2"><label class="field"><span>Nombre del proyecto *</span><input class="input" name="projectName" required placeholder="Ej. Obra, contrato, proyecto o frente"></label><label class="field"><span>Número / nombre del PNF o pedido *</span><input class="input" name="orderRef" required placeholder="PNF / PVC / PVN / OC"></label></div><div class="grid grid-2"><label class="field"><span>Cliente / tercero</span><input class="input" name="customer" placeholder="Cliente, obra o tercero"></label><label class="field"><span>Responsable de proyectos</span><input class="input" name="commercialOwner" value="'+esc(state.user.name||'')+'"></label></div><div class="grid grid-2"><label class="field"><span>Tipo de entrega</span><select class="select" name="deliveryType"><option value="punto">Se recoge en punto</option><option value="local">Despacho local</option><option value="nacional">Despacho nacional</option><option value="obra">Entrega en obra/proyecto</option></select></label><label class="field"><span>Prioridad</span><select class="select" name="projectPriority"><option value="Normal">Normal</option><option value="Alta">Alta</option><option value="Crítica">Crítica</option></select></label></div><label class="check-card"><input type="checkbox" name="pickupPoint"> El proyecto se recoge en punto</label><label class="field"><span>Qué van a montar / detalle de materiales *</span><textarea class="textarea" name="itemsDetail" required placeholder="Referencias, cantidades, metros, observaciones del PNF o pedido, cortes requeridos, lugar de entrega."></textarea></label><label class="field"><span>Observaciones adicionales</span><textarea class="textarea" name="notes" placeholder="Dirección, contacto, condiciones de despacho, documentos del proyecto o aclaraciones."></textarea></label><button class="btn btn-primary" type="submit">Crear solicitud de proyecto</button></form>'));
  qs("#projectOrderForm").onsubmit=function(e){e.preventDefault();saveProjectOrder(new FormData(e.target));};
}
function saveProjectOrder(fd){
  if(!fd.get("requiredDate")){alert("Debe indicar para qué día necesitan el PNF o pedido de proyecto.");return;}
  if(!fd.get("itemsDetail")){alert("Debe especificar qué van a montar o el detalle de materiales del proyecto.");return;}
  var id=uid("PROY");
  var doc={id:id,requestType:fd.get("requestType")||"Pedido",projectName:fd.get("projectName")||"",orderRef:fd.get("orderRef")||"",customer:fd.get("customer")||"",commercialOwner:fd.get("commercialOwner")||state.user.name||"",deliveryType:fd.get("deliveryType")||"",pickupPoint:!!fd.get("pickupPoint"),requiredDate:fd.get("requiredDate")||"",projectPriority:fd.get("projectPriority")||"Normal",itemsDetail:fd.get("itemsDetail")||"",notes:fd.get("notes")||"",status:"CREADO_PROYECTOS",source:"proyectos",createdAt:now(),updatedAt:now(),createdBy:state.user.uid,createdByName:state.user.name,createdByRole:normalizeRole(state.user.role)};
  db.collection("proyectos_pedidos").doc(id).set(doc).then(function(){return createEvent({type:"PROJECT_ORDER_CREATED",detail:"Solicitud de proyecto creada: "+doc.requestType+" · "+doc.projectName+" · "+doc.orderRef+" · requerida " + doc.requiredDate,targetRole:"coordinador_logistico",visibleRoles:["proyectos","coordinador_logistico","jefe_logistica","admin","super_admin"]}).catch(function(){return null;});}).then(loadData).then(function(){closeDrawer();renderProjectOrders();}).catch(function(e){showError(e.message||e);});
}
function projectOrderToCase(id){
  var p=(state.projectOrders||[]).filter(function(x){return x.id===id;})[0];if(!p)return;
  var caseId=uid("CASO");
  var delivery=p.pickupPoint?"cliente_recoge":(p.deliveryType==="nacional"?"despacho_nacional":(p.deliveryType==="local"||p.deliveryType==="obra"?"despacho_local":""));
  var c={id:caseId,reference:p.orderRef||p.projectName,client:p.customer||p.projectName,description:"Solicitud de proyecto: "+(p.requestType||"Pedido")+". Proyecto: "+(p.projectName||"")+". Requerido para: "+(p.requiredDate||"Sin fecha")+". Detalle: "+(p.itemsDetail||"")+". "+(p.notes||""),orderKind:"PROYECTO",requestedDelivery:delivery,requiredDate:p.requiredDate||"",priority:p.projectPriority||"Normal",priorityMode:(p.projectPriority==="Crítica"||p.projectPriority==="Alta")?"gerencia":"normal",source:"proyectos",projectId:p.id,projectName:p.projectName,projectRequestType:p.requestType||"Pedido",currentProcess:"recepcion_pedidos",status:"creado_ventas",assignedRole:primaryOwnerRole("recepcion_pedidos"),assignedName:processOwnerTitle("recepcion_pedidos"),createdAt:now(),updatedAt:now(),createdBy:state.user.uid,createdByName:state.user.name,createdByRole:normalizeRole(state.user.role),checklist:{},processStats:{}};
  processes.recepcion_pedidos.checklist.forEach(function(x){c.checklist[x]="pending";});
  db.collection("cases").doc(caseId).set(c).then(function(){return db.collection("proyectos_pedidos").doc(id).update({status:"ENVIADO_A_FLUJO",caseId:caseId,updatedAt:now(),updatedBy:state.user.uid});}).then(function(){return createEvent({type:"PROJECT_ORDER_TO_CASE",detail:"Proyecto enviado al flujo operativo: "+(p.projectName||p.orderRef),caseId:caseId,targetRole:"coordinador_logistico",visibleRoles:["proyectos","coordinador_logistico","jefe_logistica","admin","super_admin"]}).catch(function(){return null;});}).then(loadData).then(renderProjectOrders).catch(function(e){showError(e.message||e);});
}
function receptionConformityOptionsHtml(selected){
  var opts=["Conforme","Conforme con observación","Retenido"];
  return opts.map(function(x){return '<option value="'+esc(x)+'" '+(String(selected||"")===x?'selected':'')+'>'+esc(x)+'</option>';}).join("");
}
function normalizeReceptionConformity(v){return stripAccents(String(v||"").trim().toLowerCase()).replace(/[\s\-]+/g,"_");}
function receptionConformityIsNovelty(v){var x=normalizeReceptionConformity(v);return x==="retenido"||x==="no_conforme";}
function receptionIsOpen(r){return r && r.status!=="CERRADO" && !r.closedAt;}
function renderReceptionGoods(){
  if(!canAccessReceptionGoods()){layout(header("Recepción de mercancía","Acceso restringido.")+'<div class="empty">Este módulo solo puede verlo Super Admin y el rol Líder de recepción.</div>');return;}
  var list=state.receptions||[];
  var stickers=state.receptionStickers||[];
  var open=list.filter(function(x){return x.status!=="CERRADO";}).length;
  var retained=list.filter(function(x){return receptionConformityIsNovelty(x.conformity)&&x.status!=="CERRADO";}).length;
  var findings=list.reduce(function(n,x){return n+(x.findings&&x.findings.length?x.findings.length:0);},0);
  var conformes=list.filter(function(x){return receptionConformityIsFullConforme(x.conformity);}).length;
  var byLocation=receptionStickerCountBy(stickers,function(x){return x.location||x.ubicacion||"Sin ubicación";}).slice(0,5);
  var byMaterial=receptionStickerCountBy(stickers,function(x){return x.materialName||x.material||x.descripcion||"Sin material";}).slice(0,5);
  var byPurchase=receptionStickerCountBy(stickers,function(x){return receptionStickerPurchaseOrder(x)||"Sin OC";}).slice(0,5);
  var stickerRows=stickers.slice(0,50).map(function(st){var po=receptionStickerPurchaseOrder(st);var delSticker=canDeleteReceptionStickers()?'<button class="btn btn-small btn-danger" data-action="deleteReceptionSticker" data-id="'+esc(st.id||'')+'">Eliminar</button>':'';return '<tr><td><strong>'+esc(po||'Sin OC')+'</strong><br><small>'+esc(st.documentNumber||'')+'</small></td><td><strong>'+esc(st.materialName||st.material||'Material')+'</strong><br><small>'+esc(st.reference||st.referencia||'')+'</small></td><td>'+esc(st.quantity||st.cantidad||'')+' '+esc(st.unit||st.unidad||'')+'</td><td>'+esc(st.location||st.ubicacion||'')+'</td><td>'+esc(st.measures||st.medidas||'')+'</td><td>'+esc(st.entryDate||'')+'</td><td>'+esc(st.responsibleName||st.responsableIngreso||'')+'</td><td><span class="chip success">'+esc(st.status||'Conforme')+'</span><br><small>'+esc(st.printStatus||'Pendiente impresión')+'</small></td><td><div class="top-actions"><button class="btn btn-small btn-primary" data-action="printReceptionSticker" data-id="'+esc(st.id||'')+'">Imprimir</button>'+(po?'<button class="btn btn-small btn-gold" data-action="printReceptionStickerPO" data-po="'+esc(po)+'">Imprimir OC</button>':'')+delSticker+'</div></td></tr>';}).join('');
  var rows=list.map(function(r){var non=(r.findings||[]).length;var del=canDeleteReceptionGoods()?'<button class="btn btn-small btn-danger" data-action="deleteReceptionGoods" data-id="'+esc(r.id)+'">Eliminar</button>':'';var stickerBtn=receptionConformityIsFullConforme(r.conformity)?'<button class="btn btn-small btn-gold" data-action="openReceptionStickerWizard" data-id="'+esc(r.id)+'">Stickers</button>':'';var stForReception=stickers.filter(function(st){return st.receptionId===r.id;});var stCount=stForReception.length;var printBtn=stCount?'<button class="btn btn-small btn-primary" data-action="printReceptionStickersReception" data-id="'+esc(r.id)+'">Imprimir OC</button>':'';return '<tr><td><strong>'+esc(r.documentNumber||r.id)+'</strong><br><small>'+esc(r.supplier||'')+'</small><br><small>OC: '+esc(receptionPurchaseOrder(r)||'Sin OC')+'</small></td><td>'+esc(r.receiptType||'Ingreso')+'</td><td>'+esc(r.status||'ABIERTO')+'</td><td>'+esc(r.conformity||'Pendiente')+'</td><td>'+non+'</td><td>'+stCount+'</td><td>'+fmtDate(r.createdAt)+'</td><td><div class="top-actions"><button class="btn btn-small btn-primary" data-action="openReceptionGoods" data-id="'+esc(r.id)+'">Abrir</button>'+stickerBtn+printBtn+del+'</div></td></tr>';}).join('');
  layout(header("Recepción de mercancía","Control de ingresos, chequeos, stickers imprimibles por orden de compra y base descargable para conciliación interna.",'<button class="btn btn-primary" data-action="receptionGoodsModal">Nuevo ingreso</button> <button class="btn btn-gold" data-action="exportReceptionStickers">Exportar base stickers</button> <button class="btn" data-action="refreshReceptionGoods">Actualizar</button>')+
    '<section class="grid grid-4"><article class="card kpi"><span>Ingresos</span><strong>'+list.length+'</strong><small>Registros</small></article><article class="card kpi"><span>Conformes</span><strong>'+conformes+'</strong><small>Generan stickers</small></article><article class="card kpi"><span>Stickers</span><strong>'+stickers.length+'</strong><small>Etiquetas imprimibles</small></article><article class="card kpi"><span>Retenidos</span><strong>'+retained+'</strong><small>Requieren decisión</small></article></section>'+ 
    '<section class="card" style="margin-top:16px"><div class="notice"><strong>Flujo de stickers físicos:</strong> cuando el ingreso queda <strong>Conforme</strong>, se crea una base de stickers por <strong>orden de compra</strong>. Cada sticker puede imprimirse y pegarse en la mercancía; también puede imprimirse toda la OC en lote.</div><h3>Ingresos de mercancía</h3><div class="table-wrap"><table><thead><tr><th>Documento / proveedor / OC</th><th>Tipo</th><th>Estado</th><th>Conformidad</th><th>Hallazgos</th><th>Stickers</th><th>Actualizaciones</th><th>Fecha</th><th>Acción</th></tr></thead><tbody>'+(rows||'<tr><td colspan="8">Sin ingresos registrados.</td></tr>')+'</tbody></table></div></section>'+ 
    '<section class="grid grid-3" style="margin-top:16px"><article class="card"><h3>Órdenes de compra con stickers</h3>'+miniBarsHtml(byPurchase)+'</article><article class="card"><h3>Materiales con más stickers</h3>'+miniBarsHtml(byMaterial)+'</article><article class="card"><h3>Ubicaciones principales</h3>'+miniBarsHtml(byLocation)+'</article></section>'+ 
    '<section class="card" style="margin-top:16px"><div class="section-title"><div><h3>Base de stickers de separación</h3><p>Últimos 50 registros. La exportación descarga la base completa cargada en la app.</p></div><button class="btn btn-small btn-gold" data-action="exportReceptionStickers">Descargar Excel</button></div><div class="table-wrap"><table><thead><tr><th>OC / Documento</th><th>Material</th><th>Cantidad</th><th>Ubicación</th><th>Medidas</th><th>Fecha ingreso</th><th>Responsable</th><th>Estado impresión</th><th>Acción</th></tr></thead><tbody>'+(stickerRows||'<tr><td colspan="9">Sin stickers creados.</td></tr>')+'</tbody></table></div></section>');
}
function receptionChecklist(){
  return ["Documento soporte cargado y legible","Orden/factura/remisión coincide con la mercancía","Proveedor identificado","Cantidades recibidas validadas","Referencias y descripciones coinciden","Estado físico del empaque conforme","Mercancía sin averías visibles","Lote/serial/fecha aplica y fue verificado","Unidad de medida correcta","Registro fotográfico o soporte anexo disponible","Novedades reportadas oportunamente","Mercancía apta para ingreso a inventario/almacén"];
}

function receptionConformityIsFullConforme(value){
  var v=stripAccents(String(value||"").toLowerCase()).trim();
  return v==="conforme";
}
function receptionStickerCountBy(list,fn){
  var m={};(list||[]).forEach(function(x){var k=cleanPdfValue(fn(x)||"Sin dato");m[k]=(m[k]||0)+1;});
  return Object.keys(m).map(function(k){return {label:k,value:m[k]};}).sort(function(a,b){return b.value-a.value;});
}
function defaultReceptionStickerDate(r){
  var d=(r&&(r.createdAt||r.updatedAt))||now();
  try{return new Date(d).toISOString().slice(0,10);}catch(e){return new Date().toISOString().slice(0,10);}
}
function receptionStickerStatus(){return "Conforme";}
function receptionPurchaseOrder(r){
  r=r||{};
  return cleanPdfValue(r.purchaseOrder||r.ordenCompra||r.orderNumber||r.ocNumber||r.oc||r.documentNumber||"");
}
function receptionStickerPurchaseOrder(st){
  st=st||{};
  return cleanPdfValue(st.purchaseOrder||st.ordenCompra||st.orderNumber||st.ocNumber||st.oc||st.documentNumber||"");
}
function receptionStickerSafeFileName(value){
  return String(value||"stickers").replace(/[^a-z0-9_\-]+/gi,"_").replace(/_+/g,"_").slice(0,80)||"stickers";
}
function receptionStickerCandidateFromItem(it,r){
  it=it||{};r=r||{};
  var po=receptionPurchaseOrder(r);
  return {
    id:uid("STK"),
    purchaseOrder:po,
    orderNumber:po,
    reference:it.referencia||it.reference||it.codigo||"",
    materialName:it.descripcion||it.materialName||it.material||it.referencia||"",
    quantity:it.cantidad||it.quantity||"",
    unit:it.unidad||it.unit||"UND",
    location:it.ubicacion||it.location||"",
    measures:it.medidas||it.measures||"",
    entryDate:defaultReceptionStickerDate(r),
    responsibleName:(r.createdByName||((state.user&&state.user.name)||"")),
    status:receptionStickerStatus(),
    printStatus:"PENDIENTE_IMPRESION",
    source:"LECTOR_RECEPCION",
    documentNumber:r.documentNumber||"",
    supplier:r.supplier||""
  };
}
