        +'<div class="cell"><span>Ubicación</span><b>'+esc(st.location||st.ubicacion||'')+'</b></div>'
        +'<div class="cell"><span>Medidas</span><b>'+esc(st.measures||st.medidas||'')+'</b></div>'
        +'<div class="cell"><span>Fecha de ingreso</span><b>'+esc(st.entryDate||'')+'</b></div>'
        +'<div class="cell"><span>Responsable de ingreso</span><b>'+esc(st.responsibleName||st.responsableIngreso||'')+'</b></div>'
      +'</div>'
      +'<div class="footer">'
        +'<div><div class="metaLine">Generado el<strong>'+esc(new Date().toLocaleString('es-CO'))+'</strong></div><div class="metaLine">Estado de impresión<strong>'+esc(st.printStatus||'PENDIENTE_IMPRESION')+'</strong></div></div>'
        +'<div class="stickerCodeWrap"><span>Código sticker</span><div class="code">'+esc(st.id||'')+'</div><small class="note">Pegar en la mercancía</small></div>'
