        proceso:k, procesoNombre:processTitle(k), inicio:processStageStart(c,k,st), fin:processStageEnd(c,k,st),
        activo:active, espera:wait, muerto:dead, total:elapsed, esperaDesde:caseCurrentWaitStartForProcess(c,k),
