function startActive(c){
  if(c.deadStartedAt){procStats(c,c.currentProcess).deadMs+=workingMsSince(c.deadStartedAt);}
  c.deadStartedAt=null;c.activeStartedAt=now();c.status="en_proceso";c.assignedTo=state.user.uid;c.assignedName=state.user.name;registerProcessResponsible(c,c.currentProcess,state.user,"Inicio de trabajo");addStateHistory(c,"valor","Inicio de trabajo en "+processTitle(c.currentProcess),{tipo_estado:"valor",fecha_hora_inicio_estado:c.activeStartedAt});
}
function stopActive(c){
  if(c.activeStartedAt){procStats(c,c.currentProcess).activeMs+=workingMsSince(c.activeStartedAt);}
  c.activeStartedAt=null;
}
function stopWait(c){
  if(c.waitStartedAt){procStats(c,c.currentProcess).waitMs+=workingMsSince(c.waitStartedAt);}
  c.waitStartedAt=null;
}
function normalizeAssignmentUsers(users){
  var seen={}, out=[];
  (users||[]).forEach(function(raw){
    var u=raw;
    if(typeof raw==="string"){
      var txt=String(raw||"").trim();
      if(!txt)return;
      if(txt.charAt(0)==="{"){
        try{u=JSON.parse(txt);}catch(e){u={uid:txt};}
      }else{
        u=findUserByAnyIdentifier(txt)||{uid:txt,id:txt};
      }
    }
    if(!u || typeof u!=="object")return;
    var profile=findUserByAnyIdentifier(u.id||u.uid||u.userId||u.email||u.name)||{};
    var uidValue=String(profile.id||profile.uid||u.id||u.uid||u.userId||"").trim();
    if(!uidValue && typeof raw==="string")uidValue=String(raw||"").trim();
    if(!uidValue || seen[uidValue])return;
    seen[uidValue]=1;
    out.push({
      uid:uidValue,
      id:uidValue,
      profileUid:profile.uid||u.uid||"",
      uidAliases:userIdentityAliases(Object.assign({},profile,u,{id:uidValue,uid:uidValue})),
      name:u.name||u.displayName||profile.name||profile.displayName||u.email||profile.email||uidValue,
      email:u.email||profile.email||"",
      role:normalizeRole(u.role||profile.role||"aux_logistica")
    });
  });
  return out;
}
function applyPersonalAssignment(c,next,assignmentUsers){
  var users=normalizeAssignmentUsers(assignmentUsers);
  c.assignedUsers=[];c.assignedUserIds=[];c.assignedUid="";c.assignedEmail="";
  if(isDeliveryProcess(next) && applyDeliveryRouteAssignment(c,next)){
    return;
  }
  if(next==="alistamiento" && users.length){
    c.assignedUsers=users;
    c.assignedUserIds=uniqueArray(users.reduce(function(acc,u){return acc.concat(userIdentityAliases(u));},[]));
    c.assignedTo=users[0].uid;
    c.assignedUid=users[0].uid;
    c.assignedEmail=users[0].email||"";
    c.assignedName=users.map(function(u){return u.name||u.email||u.uid;}).join(" / ");
    c.assignedRole="aux_logistica";
  }else{
    c.assignedTo="";
    c.assignedEmail="";
    c.assignedName=processOwnerTitle(next);
    c.assignedRole=primaryOwnerRole(next);
  }
}
function assignToProcess(c,next,detail,assignmentUsers){
  if(c && next==="recepcion_pedidos" && pveShouldBeForcedToPurchases(c)){
    ensurePvePurchasingMetadata(c,"Bloqueo V221: ningún PVE sin liberar por Compras puede entrar directo a Recepción");
    next="compras";
    detail="PVE sin liberación de Compras. Se redirige primero a Compras antes de Recepción.";
    assignmentUsers=null;
  }
  closeSeparationIfCajaReleases(c,next);
  var current=c.currentProcess;
  stopActive(c);stopWait(c);
  procStats(c,current).completedAt=now();
  addStateHistory(c,"handoff","Cambio de etapa: "+processTitle(current)+" → "+processTitle(next),{fromProcess:current,toProcess:next,fecha_hora_fin_estado:procStats(c,current).completedAt,tipo_estado:"valor"});
  c.currentProcess=next;c.status="asignado";applyPersonalAssignment(c,next,assignmentUsers);c.deadStartedAt=now();c.activeStartedAt=null;c.waitStartedAt=null;c.openRequirement=null;c.checklist={};
  if(isDeliveryProcess(next)){c.deliveryType=expectedDeliveryTypeForProcess(next);}
  var s=procStats(c,next);s.startedAt=s.startedAt||now();s.handoffs=Number(s.handoffs||0)+1;
  processes[next].checklist.forEach(function(x){c.checklist[x]="pending";});
  if(next==="alistamiento")applyAlistamientoAutoChecklist(c);
  var assigned=assignedPeopleText(c);
  addStateHistory(c,"asignado","Entrada a "+processTitle(next)+(assigned?" · Asignado a: "+assigned:" · Bandeja general"),{fromProcess:current,toProcess:next,tipo_estado:"asignado",fecha_hora_inicio_estado:c.deadStartedAt,assignedUserIds:c.assignedUserIds||[]});
  return persistCase(c,{type:"TRANSFER_SENT",detail:(detail||("Relevo a "+processTitle(next)))+(assigned?" · Asignado a: "+assigned:""),assignedUserIds:c.assignedUserIds||[],assignedUsers:c.assignedUsers||[]});
}

function openAlistamientoAssignment(id){
  var c=caseById(id);if(!c)return;
  normalizeReceptionDocumentFlow(c);
  if(c.currentProcess==="recepcion_pedidos" && separationActive(c)){addStateHistory(c,"pago_pendiente","Recepción continúa a alistamiento con anotación de pago pendiente. Logística liberará cuando se confirme pago.",{tipo_estado:"pago_pendiente",toProcess:"alistamiento"});}
  if(c.currentProcess==="recepcion_pedidos" && !canAssignAlistamientoFromReception(c)){alert("Este usuario no tiene permiso para enviar Recepción a Alistamiento ni asignar responsables.");return;}
  if(c.currentProcess==="recepcion_pedidos" && !receptionPdfIsComplete(c)){alert("Recepción no puede avanzar: falta "+(receptionPdfMissingReason(c)||"completar la validación documental")+". La validación ahora solo bloquea si realmente faltan líneas, PDF leído/cargado o compromiso; no bloquea por nombre de campo Drive.");return;}
  if(c.currentProcess!=="recepcion_pedidos" && c.currentProcess!=="alistamiento"){alert("La asignación individual solo aplica al paso de Alistamiento.");return;}
  if(c.currentProcess==="alistamiento" && !canManageAlistamientoAssignment(c)){alert("Solo coordinación, jefe logística o administrador puede cambiar esta asignación.");return;}
  var users=alistamientoAssignableUsers();
  var selected=caseAssignedUserIds(c);
  var rows=users.map(function(u){
    var idu=u.uid||u.id, checked=selected.indexOf(idu)>=0?'checked':'';
    return '<label class="check-card"><input type="checkbox" name="alistamientoUser" value="'+esc(idu)+'" '+checked+'> <strong>'+esc(u.name||u.email||idu)+'</strong><br><small>'+esc(roleTitle(u.role||"aux_logistica"))+(u.email?' · '+esc(u.email):'')+'</small></label>';
  }).join('');
  if(!rows)rows='<div class="notice warning"><strong>No encontré usuarios activos con rol Auxiliar logística.</strong><br>El rol que asigna puede ser Super Admin o Logística/despacho unificado, pero las personas a seleccionar deben estar activas con rol Auxiliar logística.</div>';
  drawer(modal('Asignar solicitud de alistamiento','<form class="form" id="alistAssignForm"><div class="notice"><strong>Recepción o Logística/despacho unificado define quién alista:</strong> seleccione de 1 a 3 auxiliares logísticos. El pedido quedará visible para los usuarios seleccionados y el VSM guardará la asignación individual.</div>'+rows+'<label class="field"><span>Observación de asignación</span><textarea class="textarea" name="detail" placeholder="Ej.: pedido grande, asignar a dos auxiliares; pedido urgente; separar por referencias."></textarea></label><button class="btn btn-primary" type="submit">'+(c.currentProcess==="recepcion_pedidos"?'Enviar a alistamiento':'Guardar asignación')+'</button></form>'));
  qs('#alistAssignForm').onsubmit=function(e){
    e.preventDefault();
    var fd=new FormData(e.target);
    var ids=qsa('input[name="alistamientoUser"]:checked',e.target).map(function(x){return x.value;});
    if(users.length && !ids.length){alert('Seleccione al menos un auxiliar de alistamiento.');return;}
    if(ids.length>3){alert('Seleccione máximo 3 personas para evitar reprocesos y confusión.');return;}
    var picked=users.filter(function(u){return ids.indexOf(String(u.uid||u.id||""))>=0;});
    if(c.currentProcess==="recepcion_pedidos"){
      assignToProcess(c,'alistamiento',fd.get('detail')||'Recepción envía a alistamiento con responsable definido.',picked).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});
    }else{
      applyPersonalAssignment(c,'alistamiento',picked);
      addStateHistory(c,'asignacion','Asignación de alistamiento actualizada: '+(assignedPeopleText(c)||'Bandeja general'),{tipo_estado:'asignacion',assignedUserIds:c.assignedUserIds||[]});
      persistCase(c,{type:'ALISTAMIENTO_ASSIGNMENT_UPDATED',detail:(fd.get('detail')||'Asignación de alistamiento actualizada')+(assignedPeopleText(c)?' · '+assignedPeopleText(c):''),assignedUserIds:c.assignedUserIds||[],assignedUsers:c.assignedUsers||[]}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});
    }
  };
}

function openEvidence(id){
  var c=caseById(id);if(!c)return;
  if(!canUploadEvidenceForCase(c)){alert("Este usuario no tiene permiso para anexar evidencias en este caso.");return;}
  var current=c.currentProcess||"recepcion_pedidos";
  drawer(modal("Subir evidencia a Drive",'<form class="form" id="evidenceForm"><div class="notice">La evidencia se guarda en Google Drive. Puede seleccionar mínimo 1 y máximo 10 archivos; si son imágenes, se verán como mini galería.</div><section class="grid grid-2"><label class="field"><span>Proceso / módulo de la evidencia</span><select class="select" name="processKey" id="evidenceProcessSelect">'+evidenceProcessOptions(current)+'</select></label><label class="field"><span>Tipo de evidencia</span><select class="select" name="evidenceType" id="evidenceTypeSelect">'+evidenceTypeOptions()+'</select></label></section><label class="field"><span>Archivos o fotos</span><input class="input" type="file" name="evidence" id="evidenceInput" accept="image/*,application/pdf,.pdf,.doc,.docx,.xls,.xlsx,.csv" capture="environment" data-mobile-upload="true" multiple required><small class="muted">Mínimo 1 y máximo 10 archivos.</small></label><label class="field"><span>Descripción</span><textarea class="textarea" name="detail" placeholder="Ej.: PDF del pedido, foto del carro, soporte de despacho, guía, novedad, evidencia de alistamiento, soporte de caja o auditoría."></textarea></label><div class="notice" id="evidenceStatus">Seleccione archivo(s) y guarde. No se registra en el caso hasta que Drive confirme el cargue.</div><button class="btn btn-primary" type="submit">Guardar evidencia en Drive</button></form>'));
  var processSelect=qs("#evidenceProcessSelect"), typeSelect=qs("#evidenceTypeSelect");
  if(typeSelect)typeSelect.value=defaultEvidenceTypeForProcess(current);
  if(processSelect && typeSelect){processSelect.onchange=function(){typeSelect.value=defaultEvidenceTypeForProcess(processSelect.value);};}
  qs("#evidenceForm").onsubmit=function(e){
    e.preventDefault();
    var fd=new FormData(e.target), files=selectedUploadFiles(qs("#evidenceInput"),"archivos");
    if(!files)return;
    var processKey=fd.get("processKey")||c.currentProcess;
    var evidenceType=fd.get("evidenceType")||defaultEvidenceTypeForProcess(processKey);
    var statusEl=qs("#evidenceStatus");if(statusEl)statusEl.textContent="Subiendo evidencia a Drive...";
    uploadFilesToDriveGallery(files,c,{processName:processTitle(processKey),processKey:processKey,evidenceType:evidenceType,fileNamePrefix:evidenceType},statusEl).then(function(uploads){
      appendEvidenceGallery(c,uploads,fd.get("detail")||"",{processKey:processKey,processName:processTitle(processKey),evidenceType:evidenceType});
      return persistCase(c,{type:"PROCESS_EVIDENCE_UPLOADED",process:processKey,detail:(fd.get("detail")||(files.length+" archivo(s)"))+" · "+processTitle(processKey)+" · "+evidenceType}).then(function(){return Promise.all(uploads.map(function(x){return persistEvidenceDocument(c,x.upload,fd.get("detail")||"");}));});
    }).then(function(){closeDrawer();renderDetail(c.id);}).catch(function(err){if(statusEl)statusEl.textContent="No fue posible cargar la evidencia: "+(err.message||err);showError(err.message||err);});
  };
}

function openWait(id){
  var c=caseById(id), def=processes[c.currentProcess];
  drawer(modal("Requerimiento / espera",'<form class="form" id="waitForm"><label class="field"><span>Motivo</span><select class="select" name="reason">'+def.waits.map(function(w){return'<option>'+esc(w)+'</option>';}).join("")+'</select></label><label class="field"><span>Área responsable</span><select class="select" name="role"><option value="ventas">Ventas</option><option value="compras">Compras</option><option value="coordinador_logistico">Logística / despacho</option><option value="jefe_logistica">Jefe de logística</option><option value="aux_logistica">Auxiliar logística</option><option value="gerencia">Gerencia</option></select></label><label class="field"><span>Detalle</span><textarea class="textarea" name="detail"></textarea></label><button class="btn btn-primary" type="submit">Enviar requerimiento</button></form>'));
  qs("#waitForm").onsubmit=function(e){e.preventDefault();var fd=new FormData(e.target);stopActive(c);c.status=fd.get("role")==="ventas"?"espera_ventas":"en_espera";c.waitStartedAt=now();addStateHistory(c,"espera",fd.get("reason")+" · "+(fd.get("detail")||""),{tipo_estado:"espera",motivo_novedad:fd.get("reason"),fecha_hora_inicio_estado:c.waitStartedAt});c.assignedRole=fd.get("role");c.assignedName=roleTitle(fd.get("role"));c.openRequirement={reason:fd.get("reason"),detail:fd.get("detail"),targetRole:fd.get("role"),sentAt:now(),sentBy:state.user.uid,returnProcess:c.currentProcess};c.totalRequirements=Number(c.totalRequirements||0)+1;persistCase(c,{type:"REQUIREMENT_SENT",reason:fd.get("reason"),detail:fd.get("detail"),targetRole:fd.get("role")}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});};
}
function openAnswer(id){
  var c=caseById(id);
  drawer(modal("Responder / resolver requerimiento",'<form class="form" id="ansForm"><label class="field"><span>Respuesta</span><textarea class="textarea" name="detail" required></textarea></label><button class="btn btn-primary" type="submit">Resolver y devolver al proceso</button></form>'));
  qs("#ansForm").onsubmit=function(e){
    e.preventDefault();
    var fd=new FormData(e.target);
    var detail=String(fd.get("detail")||"");
    var req=c.openRequirement||null;
    var salesBlock=(req&&normalizeRole(req.targetRole)==="ventas")||c.status==="espera_ventas"||normalizeRole(c.assignedRole)==="ventas";
    if(salesBlock){
      releaseCaseFromSalesBlock(c,detail,"Requerimiento resuelto por Ventas");
    }else{
      var ret=req?req.returnProcess:c.currentProcess;
      if(!processes[ret])ret=c.currentProcess||"recepcion_pedidos";
      stopWait(c);
      if(req && c.requirements){
        c.requirements.forEach(function(r){
          var sameCut=(req.cutId&&r.cutId===req.cutId)||(!req.cutId&&!r.cutId);
          if(requirementIsPending(r) && normalizeRole(r.targetRole)===normalizeRole(req.targetRole) && sameCut){
            r.status="resuelto";
            r.answeredAt=now();
            r.answeredBy=state.user.uid;
            r.answeredByName=state.user.name;
            r.answer=detail;
          }
        });
      }
      c.currentProcess=ret;c.status="asignado";clearCasePersonalAssignment(c,ret);c.deadStartedAt=now();c.activeStartedAt=null;c.waitStartedAt=null;c.openRequirement=null;
      addStateHistory(c,"requerimiento_resuelto","Requerimiento resuelto y devuelto a "+processTitle(ret)+": "+detail,{tipo_estado:"requerimiento_resuelto",toProcess:ret,motivo_novedad:detail});
    }
    persistCase(c,{type:"REQUIREMENT_ANSWERED",detail:detail,targetRole:c.assignedRole,visibleRoles:["admin","super_admin","super_administrador","gerencia","jefe_logistica",c.assignedRole,"ventas"]}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});
  };
}

function setChecklistValues(c, values){
  c.checklist=c.checklist||{};
  Object.keys(values||{}).forEach(function(k){if(c.checklist[k]!==undefined)c.checklist[k]=values[k];});
}
function openInitialCommitment(id){
  var c=caseById(id);if(!c)return;
  var pdf=casePdfUrl(c)?'<a class="btn btn-small" href="'+esc(casePdfUrl(c))+'" target="_blank" rel="noopener">Abrir PDF del pedido</a>':'<span class="chip warning">PDF pendiente</span>';
  drawer(modal("Compromiso inicial de mercancía",'<form class="form" id="initialCommitForm"><div class="notice">Revise el documento, confirme la reserva de la mercancía y luego envíe el pedido a alistamiento.</div>'+pdf+'<section class="grid grid-2"><label class="check-card"><input type="checkbox" name="pdfOk"> PDF corresponde al pedido</label><label class="check-card"><input type="checkbox" name="itemsOk"> Referencias y cantidades revisadas</label><label class="check-card"><input type="checkbox" name="commitOk"> Mercancía comprometida/bloqueada</label><label class="check-card"><input type="checkbox" name="noCancel"> Sin devolución ni cancelación pendiente</label></section><label class="field"><span>Resultado</span><select class="select" name="result" required><option value="COMPROMETIDO">Comprometer y enviar a alistamiento</option><option value="REQUERIMIENTO_VENTAS">Generar requerimiento a Ventas</option><option value="CANCELADO">Cancelar / terminar proceso</option></select></label><label class="field"><span>Detalle / observación</span><textarea class="textarea" name="detail" placeholder="Ej.: mercancía reservada, pedido parcial, devolución, cancelación o ajuste requerido."></textarea></label><button class="btn btn-primary" type="submit">Guardar compromiso</button></form>'));
  qs("#initialCommitForm").onsubmit=function(e){
    e.preventDefault();var fd=new FormData(e.target), result=fd.get("result"), detail=fd.get("detail")||"";
    c.documentFlow=c.documentFlow||{};
    if(!receptionPdfIsComplete(c) && result==="COMPROMETIDO"){alert("No puede comprometer mercancía si Recepción no cargó, leyó y guardó el soporte oficial PDF/CSV con líneas detectadas.");return;}
    if(result==="CANCELADO"){
      stopActive(c);stopWait(c);c.status="cancelado";c.closedAt=now();c.documentFlow.initialCommitmentStatus="CANCELADO";c.documentFlow.initialCommitmentDetail=detail;addStateHistory(c,"cancelacion",detail||"Cancelado en compromiso inicial",{tipo_estado:"cancelacion",motivo_novedad:detail});
      persistCase(c,{type:"INITIAL_COMMITMENT_CANCELLED",detail:detail}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});return;
    }
    if(result==="REQUERIMIENTO_VENTAS"){
      stopActive(c);c.status="espera_ventas";c.waitStartedAt=now();c.assignedRole="ventas";c.assignedName=roleTitle("ventas");c.openRequirement={reason:"Requiere corrección de Ventas",detail:detail,targetRole:"ventas",sentAt:now(),sentBy:state.user.uid,returnProcess:"compromiso_mercancia"};c.totalRequirements=Number(c.totalRequirements||0)+1;c.documentFlow.initialCommitmentStatus="REQUERIMIENTO_VENTAS";c.documentFlow.initialCommitmentDetail=detail;addStateHistory(c,"espera",detail||"Requerimiento a Ventas desde compromiso inicial",{tipo_estado:"espera",motivo_novedad:"Requerimiento a Ventas"});
      persistCase(c,{type:"INITIAL_COMMITMENT_REQUIREMENT",detail:detail,targetRole:"ventas"}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});return;
    }
    if(!fd.get("pdfOk")||!fd.get("itemsOk")||!fd.get("commitOk")||!fd.get("noCancel")){alert("Para comprometer debe confirmar todos los checks del compromiso inicial.");return;}
    c.documentFlow.initialCommitmentStatus="SI";c.documentFlow.initialCommitmentDetail=detail||"Mercancía reservada y validada en el proceso interno";c.documentFlow.initialCommitmentAt=now();c.documentFlow.initialCommitmentBy=state.user.name;
    setChecklistValues(c,{"Pedido recibido desde recepción":"ok","PDF revisado contra pedido":"ok","Pedido correcto para comprometer":"ok","Referencias principales identificadas":"ok","Cantidades revisadas":"ok","Cortes automáticos identificados si aplica":"ok","Mercancía reservada y validada en el proceso interno":"ok","Novedades de devolución o cancelación descartadas":"ok","Pedido liberado para alistamiento":"ok"});
    assignToProcess(c,"alistamiento",detail||"Compromiso inicial realizado; pedido pasa a alistamiento").then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});
  };
}
function openRatificationCommitment(id){
  var c=caseById(id);if(!c)return;
  var cuts=cutDoneCount(c);
  var pendingCuts=cuts.total-cuts.done;
  var pdf=casePdfUrl(c)?'<a class="btn btn-small" href="'+esc(casePdfUrl(c))+'" target="_blank" rel="noopener">Abrir PDF del pedido</a>':'<span class="chip warning">PDF pendiente</span>';
  drawer(modal("Ratificar compromiso antes de facturar",'<form class="form" id="ratifyCommitForm"><div class="notice">Antes de facturar se confirma que el compromiso inicial sigue válido, que el producto es el correcto y que no hay devolución, cancelación o corte pendiente.</div>'+pdf+(pendingCuts>0?'<div class="notice danger"><strong>Atención:</strong> hay '+pendingCuts+' corte(s) pendiente(s). No debería ratificarse hasta finalizar cortes.</div>':'')+'<section class="grid grid-2"><label class="check-card"><input type="checkbox" name="productOk"> Era el producto correcto</label><label class="check-card"><input type="checkbox" name="refOk"> Referencia correcta contra PDF</label><label class="check-card"><input type="checkbox" name="qtyOk"> Cantidad correcta</label><label class="check-card"><input type="checkbox" name="unitOk"> Unidad de medida correcta</label><label class="check-card"><input type="checkbox" name="cutsOk" '+(pendingCuts>0?'':'checked')+'> Cortes finalizados si aplica</label><label class="check-card"><input type="checkbox" name="noCancel"> Sin devolución ni cancelación</label></section><label class="field"><span>Resultado</span><select class="select" name="result" required><option value="RATIFICADO">Ratificar compromiso y enviar a facturación</option><option value="REQUERIMIENTO_VENTAS">Generar requerimiento a Ventas</option><option value="CANCELADO">Cancelar / terminar proceso</option></select></label><label class="field"><span>Detalle / observación</span><textarea class="textarea" name="detail" placeholder="Ej.: compromiso ratificado, devolución detectada, producto diferente, cantidad incorrecta o cancelación."></textarea></label><button class="btn btn-primary" type="submit">Guardar ratificación</button></form>'));
  qs("#ratifyCommitForm").onsubmit=function(e){
    e.preventDefault();var fd=new FormData(e.target), result=fd.get("result"), detail=fd.get("detail")||"";
    c.documentFlow=c.documentFlow||{};
    if(result==="RATIFICADO" && pendingCuts>0){alert("No puede ratificar si hay cortes pendientes por finalizar.");return;}
    if(result==="CANCELADO"){
      stopActive(c);stopWait(c);c.status="cancelado";c.closedAt=now();c.documentFlow.finalCommitmentStatus="CANCELADO";c.documentFlow.finalCommitmentDetail=detail;addStateHistory(c,"cancelacion",detail||"Cancelado en ratificación de compromiso",{tipo_estado:"cancelacion",motivo_novedad:detail});
      persistCase(c,{type:"FINAL_COMMITMENT_CANCELLED",detail:detail}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});return;
    }
    if(result==="REQUERIMIENTO_VENTAS"){
      stopActive(c);c.status="espera_ventas";c.waitStartedAt=now();c.assignedRole="ventas";c.assignedName=roleTitle("ventas");c.openRequirement={reason:"Diferencia en ratificación de compromiso",detail:detail,targetRole:"ventas",sentAt:now(),sentBy:state.user.uid,returnProcess:"ratificacion_compromiso"};c.totalRequirements=Number(c.totalRequirements||0)+1;c.documentFlow.finalCommitmentStatus="REQUERIMIENTO_VENTAS";c.documentFlow.finalCommitmentDetail=detail;addStateHistory(c,"espera",detail||"Requerimiento a Ventas desde ratificación",{tipo_estado:"espera",motivo_novedad:"Requerimiento a Ventas"});
      persistCase(c,{type:"FINAL_COMMITMENT_REQUIREMENT",detail:detail,targetRole:"ventas"}).then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});return;
    }
    if(!fd.get("productOk")||!fd.get("refOk")||!fd.get("qtyOk")||!fd.get("unitOk")||!fd.get("cutsOk")||!fd.get("noCancel")){alert("Para ratificar debe confirmar todas las preguntas del chequeo final.");return;}
    c.documentFlow.finalCommitmentStatus="RATIFICADO";c.documentFlow.finalCommitmentDetail=detail||"Compromiso ratificado antes de facturar";c.documentFlow.finalCommitmentAt=now();c.documentFlow.finalCommitmentBy=state.user.name;
    setChecklistValues(c,{"Alistamiento validado":"ok","Cortes finalizados si aplica":"ok","Producto correcto contra PDF":"ok","Referencia correcta":"ok","Cantidad correcta":"ok","Unidad de medida correcta":"ok","Sin devolución pendiente":"ok","Sin cancelación pendiente":"ok","Compromiso inicial revisado":"ok","Reserva de mercancía ratificada":"ok","Pedido listo para facturación":"ok"});
    assignToProcess(c,"facturacion",detail||"Compromiso ratificado; pedido pasa a facturación").then(function(){closeDrawer();renderDetail(id);}).catch(function(e){showError(e.message||e);});
  };
}
function openDeliveryEvidence(id,key){
  var c=caseById(id);if(!c)return;
  if(!isDeliveryProcess(c.currentProcess)){alert("Las evidencias obligatorias de entrega solo aplican en módulos de entrega/despacho.");return;}
  if(!(canAccessProcess(state.user.role,c.currentProcess)||isAdminRoleValue(state.user.role)||isJefeLogistica())){alert("No tiene permiso para anexar evidencias en este proceso.");return;}
  var defs=deliveryEvidenceDefinitions(c.currentProcess);
  var def=defs.filter(function(x){return x.key===key;})[0]||defs[0];
  drawer(modal(def.title,'<form class="form" id="deliveryEvidenceForm"><div class="notice"><strong>'+(def.required===false?'Opcional:':'Control obligatorio:')+'</strong> '+esc(def.hint)+' Puede seleccionar mínimo 1 y máximo 10 archivos. Las imágenes se mostrarán como galería.</div><label class="field"><span>'+esc(def.title)+'</span><input class="input" type="file" name="photo" accept="'+esc(def.accept||'image/*,application/pdf,.pdf')+'" capture="environment" data-mobile-upload="true" multiple required><small class="muted">Mínimo 1 y máximo 10 archivos.</small></label><label class="field"><span>Observación</span><textarea class="textarea" name="detail" placeholder="Ej.: mercancía rotulada con sticker visible, guía de transportadora, soporte PDF o entrega final."></textarea></label><div class="notice" id="deliveryEvidenceStatus">Seleccione archivo(s) y guarde. No se marca conforme hasta que Drive confirme el cargue.</div><button class="btn btn-primary" type="submit">Guardar evidencia</button></form>'));
  qs("#deliveryEvidenceForm").onsubmit=function(e){
    e.preventDefault();
    var fd=new FormData(e.target), files=selectedUploadFiles(e.target.photo,"archivos");
    if(!files)return;
    c.deliveryEvidence=c.deliveryEvidence||{};
    if(def.key==="guiaTransportadora" && !(c.deliveryEvidence.mercanciaRotulada&&(c.deliveryEvidence.mercanciaRotulada.driveUrl||(c.deliveryEvidence.mercanciaRotulada.galleryFiles&&c.deliveryEvidence.mercanciaRotulada.galleryFiles.length)))){alert("Primero debe subir la foto de mercancía rotulada. Esa evidencia marca el cierre operativo de logística y la espera de transportadora/entrega.");return;}
    var statusEl=qs("#deliveryEvidenceStatus");if(statusEl)statusEl.textContent="Preparando evidencia...";
    uploadFilesToDriveGallery(files,c,{processName:processTitle(c.currentProcess),processKey:c.currentProcess,evidenceType:def.type,fileNamePrefix:def.type},statusEl).then(function(uploads){
      var up=uploads[0].upload, file=uploads[0].file, gallery=uploads.map(function(x){return galleryFileFromUpload(x.upload,x.file);});
      c.deliveryEvidence=c.deliveryEvidence||{};
      c.deliveryEvidence[def.key]={driveUrl:up.url||up.driveUrl||"",fileName:(uploads.length===1?(up.fileName||up.name||file.name):(uploads.length+" archivos")),fileId:up.fileId||"",uploadedAt:up.uploadedAt||now(),uploadedBy:state.user.uid,uploadedByName:state.user.name,evidenceType:def.type,process:c.currentProcess,detail:fd.get("detail")||def.hint,stamped:false,stampLabels:[],stampStyle:"",originalFileName:file.name,galleryFiles:gallery};
      c.checklist=c.checklist||{};
      c.checklist[def.checklist]="ok";
      c.deliveryFlow=c.deliveryFlow||{};
      var eventType="DELIVERY_EVIDENCE_UPLOADED";
      var eventDetail=def.title+" · "+(fd.get("detail")||"");
      if(def.key==="mercanciaRotulada"){
        stopActive(c);
        if(!c.waitStartedAt)c.waitStartedAt=now();
        c.status="espera_transportadora";
        c.deliveryFlow.logisticsCompletedAt=c.deliveryFlow.logisticsCompletedAt||c.deliveryEvidence[def.key].uploadedAt;
        c.deliveryFlow.logisticsCompletedBy=state.user.name;
        c.deliveryFlow.waitingCarrierSince=c.deliveryFlow.waitingCarrierSince||now();
        if(c.checklist["Logística finalizada, espera transportadora"]!==undefined)c.checklist["Logística finalizada, espera transportadora"]="ok";
        if(c.checklist["Logística finalizada, espera transportadora/entrega"]!==undefined)c.checklist["Logística finalizada, espera transportadora/entrega"]="ok";
        eventType="LOGISTICS_READY_FOR_CARRIER";
        eventDetail="Mercancía rotulada cargada. Termina el tiempo operativo de logística y queda en espera de transportadora/entrega.";
      }
      if(def.key==="guiaTransportadora"){
        stopActive(c);stopWait(c);
        if(c.deadStartedAt){procStats(c,c.currentProcess).deadMs+=workingMsSince(c.deadStartedAt);c.deadStartedAt=null;}
        procStats(c,c.currentProcess).completedAt=now();
        c.status="cerrado_conforme";
        c.closedAt=now();
        c.deliveryFlow.guideUploadedAt=c.deliveryEvidence[def.key].uploadedAt;
        c.deliveryFlow.guideUploadedBy=state.user.name;
        c.deliveryFlow.closedByGuide=true;
        if(c.checklist["Cierre de despacho registrado"]!==undefined)c.checklist["Cierre de despacho registrado"]="ok";
        if(c.checklist["Proceso cerrado"]!==undefined)c.checklist["Proceso cerrado"]="ok";
        addStateHistory(c,"cierre","Cierre de despacho por guía/soporte final cargado",{tipo_estado:"cierre",fecha_hora_fin_estado:c.closedAt});
        eventType="CASE_CLOSED";
        eventDetail="Despacho cerrado con guía/soporte final obligatorio.";
      }
      appendEvidenceGallery(c,uploads,fd.get("detail")||def.title,{processKey:c.currentProcess,processName:processTitle(c.currentProcess),evidenceType:def.type});
      return persistCase(c,{type:eventType,process:c.currentProcess,detail:eventDetail}).then(function(){return Promise.all(uploads.map(function(x){return persistEvidenceDocument(c,x.upload,fd.get("detail")||def.title);}));});
    }).then(function(){closeDrawer();renderDetail(c.id);}).catch(function(err){if(statusEl)statusEl.textContent="No fue posible cargar la evidencia: "+(err.message||err);showError(err.message||err);});
  };
}

