function createUser(fd){
  var name=fd.get("name"),email=fd.get("email"),pass=fd.get("password"),role=fd.get("role");
  if(role==="gerencia"&&state.users.filter(function(u){return u.role==="gerencia";}).length>=2){alert("Solo se permiten dos usuarios de gerencia.");return;}
  var second=firebase.initializeApp(window.firebaseConfig,"creator_"+Date.now());
  second.auth().createUserWithEmailAndPassword(email,pass).then(function(cred){
    return db.collection("users").doc(cred.user.uid).set({name:name,email:email,role:role,isActive:true,createdAt:now(),createdBy:state.user.uid});
  }).then(function(){
    return createEvent({type:"USER_CREATED",detail:"Usuario creado: "+name+" · "+roleTitle(role),targetRole:"admin",visibleRoles:["admin","super_admin","super_administrador","gerencia"]}).catch(function(){return null;});
  }).then(function(){return second.auth().signOut();}).then(function(){return second.delete();}).then(function(){return loadData();}).then(function(){closeDrawer();renderUsers();}).catch(function(e){showError(e.message||e);});
}
function approve(id){
  var c=caseById(id), next=nextProcessAfterCommercialGate(c);
  stopWait(c);
  c.currentProcess=next;c.status="asignado";c.assignedRole=primaryOwnerRole(next);c.assignedName=processOwnerTitle(next);c.deadStartedAt=now();c.priority="Alta";c.managerApproved=true;
  if(c.priorityApproval)c.priorityApproval.status="aprobado";
  resetChecklistForProcess(c,next);
  if(next==="compras"){c.visibleRoles=purchasesVisibleRoles();c.targetRoles=purchasesVisibleRoles();c.purchaseFlow=c.purchaseFlow||{required:true,status:"PENDIENTE_COMPRAS",source:"gerencia_pve"};}
  persistCase(c,{type:"MANAGER_APPROVED",detail:"Gerencia aprobó prioridad. Pasa a "+processTitle(next)+".",targetRole:c.assignedRole,visibleRoles:c.visibleRoles||[c.assignedRole,"admin","super_admin","super_administrador","gerencia","jefe_logistica","ventas"]}).then(function(){renderApprovals();}).catch(function(e){showError(e.message||e);});
}
function reject(id){
  var c=caseById(id);stopWait(c);c.status="cancelado";c.closedAt=now();if(c.priorityApproval)c.priorityApproval.status="rechazado";persistCase(c,{type:"MANAGER_REJECTED",detail:"Gerencia rechazó prioridad"}).then(function(){renderApprovals();}).catch(function(e){showError(e.message||e);});
}
function accept(id){var c=caseById(id);if(pveMerchandiseWaiting(c)){alert("Este PVE está en espera de mercancía. Primero marque OK mercancía para poder aceptar/iniciar.");return;}if(!canOperateCurrentProcess(c)){alert("Este pedido no está asignado a su usuario o no pertenece a su macroproceso.");return;}startActive(c);persistCase(c,{type:"CASE_ACCEPTED",detail:"Caso aceptado por "+state.user.name}).then(function(){renderDetail(id);}).catch(function(e){showError(e.message||e);});}
function transfer(id,next){
  var c=caseById(id);
  normalizeReceptionDocumentFlow(c);
  if(c && c.currentProcess==="compras" && next==="recepcion_pedidos"){
    if(!canOperateCurrentProcess(c)){alert("Este pedido no pertenece al módulo de Compras o no está asignado a su rol.");return;}
    stopActive(c);stopWait(c);
    c.purchaseFlow=c.purchaseFlow||{};
    c.purchaseFlow.status="LIBERADO";
    c.purchaseFlow.releasedAt=now();
    c.purchaseFlow.releasedBy=state.user?state.user.uid:"";
    c.purchaseFlow.releasedByName=state.user?state.user.name:"";
    c.documentFlow=c.documentFlow||{};
    c.documentFlow.purchaseReleasedAt=c.purchaseFlow.releasedAt;
    c.documentFlow.purchaseReleasedBy=c.purchaseFlow.releasedByName;
    c.documentFlow.initialCommitmentStatus="PENDIENTE_RECEPCION";
    c.visibleRoles=uniqueArray((c.visibleRoles||[]).concat(["ventas","compras","coordinador_logistico","lider_logistico","lider_logistica","jefe_logistica","admin","super_admin","super_administrador"]));
    return assignToProcess(c,"recepcion_pedidos","Compras liberó orden PVE y envía a Recepción de pedidos").then(function(){renderDetail(id);}).catch(function(e){showError(e.message||e);});
  }
  if(c && c.currentProcess==="alistamiento" && next==="facturacion")return finalizeAlistamientoToBilling(id);
  if(!canOperateCurrentProcess(c)){alert("Este pedido tiene asignación individual o no pertenece a su macroproceso.");return;}
  if(separationActive(c) && c.currentProcess==="recepcion_pedidos" && next==="alistamiento"){
    addStateHistory(c,"pago_pendiente","Recepción envía a alistamiento con anotación de pago pendiente. El proceso continúa y la liberación de pago quedará trazada por Logística/Caja.",{tipo_estado:"pago_pendiente",toProcess:"alistamiento"});
  }
  if(c.currentProcess==="recepcion_pedidos" && next!=="alistamiento"){alert("El flujo obligatorio es: Recepción de pedidos → Alistamiento. El compromiso de mercancía se registra dentro de Recepción.");return;}
  if(next==="alistamiento" && !receptionPdfIsComplete(c)){alert("Recepción no puede avanzar: falta "+(receptionPdfMissingReason(c)||"completar la validación documental")+".");return;}
  if(c.currentProcess==="alistamiento" && next!=="facturacion"){alert("Después de alistamiento el flujo continúa directamente a Facturación. Si hay cortes, primero deben quedar registrados.");return;}
  if(c.currentProcess==="alistamiento" && next==="facturacion"){
    var items=c.orderItems||[];
    var pendingItems=items.filter(function(it){return !it.alistamientoStatus||it.alistamientoStatus==="PENDIENTE";}).length;
    var noveltyItems=items.filter(function(it){return it.alistamientoStatus==="NOVEDAD"||it.alistamientoStatus==="NO_ENCONTRADO";}).length;
    if(items.length && pendingItems>0){alert("No puede enviar a facturación: todavía hay líneas del PDF pendientes por marcar en alistamiento.");return;}
    if(noveltyItems>0){alert("No puede enviar a facturación como pedido completo: hay novedades de alistamiento pendientes de resolver por líder/coordinador. Si necesita despachar lo disponible, use Crear envío parcial.");return;}
    var cd=cutDoneCount(c);if(cd.total>0 && cd.done<cd.total){alert("No puede enviar a facturación: hay cortes pendientes por finalizar y registrar.");return;}
  }
  var detail="Relevo a "+processTitle(next);
  if(separationActive(c) && c.currentProcess==="alistamiento" && next==="facturacion"){
    c.separationRequest.status="ALISTADO_PAGO_PENDIENTE";
    c.separationRequest.arrivedToBillingAt=now();
    addStateHistory(c,"pago_pendiente","Pedido alistado con pago pendiente. Facturación queda pendiente hasta que Logística/Caja registre pago confirmado.",{tipo_estado:"pago_pendiente",toProcess:"facturacion"});
    detail="Pedido de separación alistado. Pasa a Facturación con anotación de pago pendiente; Logística/Caja debe registrar pago confirmado para liberar.";
  }
  assignToProcess(c,next,detail).then(function(){renderDetail(id);}).catch(function(e){showError(e.message||e);});
}
function checklistManualBlockReason(c,item){
  if(!c)return "Caso no encontrado.";
  if(c.currentProcess==="alistamiento")return "";
  if(isDeliveryProcess(c.currentProcess) && /foto antes|mercancía subida|mercancia subida|carro cerrado|entrega final/i.test(item))return "Este punto se actualiza automáticamente al subir la foto obligatoria de entrega a Drive.";
  return "";
}
function updateCheck(el){
  var seg=el.parentNode,id=seg.getAttribute("data-id"),item=seg.getAttribute("data-check"),val=el.getAttribute("data-value"),c=caseById(id),reason=checklistManualBlockReason(c,item);
  if(!canEditGenericChecklist(c)){alert("Este checklist solo lo edita el responsable del macroproceso operativo. Ventas y Caja solo ven sus acciones necesarias.");return;}
  if(reason){alert(reason);return;}
  seg.setAttribute("data-current",val);
  qsa("button",seg).forEach(function(btn){
    var bval=btn.getAttribute("data-value");
    btn.className=(bval===val?("active "+bval):"");
  });
  var row=seg.closest?seg.closest(".check-row"):seg.parentNode;
  if(row){
    if(seg.getAttribute("data-original")!==val)row.classList.add("check-dirty");
    else row.classList.remove("check-dirty");
  }
}
function alistamientoChecklistReadyByGeneral(c){
  c=c||{};
  var list=(processes.alistamiento&&processes.alistamiento.checklist)||[];
  var checks=c.checklist||{};
  var finalReady=checks["Pedido listo para facturación"]==="ok" || checks["Pedido listo para facturación"]==="na";
  var blockingBad=list.some(function(k){return checks[k]==="bad";});
  var operational=list.filter(function(k){return k!=="Pedido listo para facturación";});
  var allOperationalOk=operational.length>0 && operational.every(function(k){return checks[k]==="ok" || checks[k]==="na";});
  return !!((finalReady || allOperationalOk) && !blockingBad);
}
function syncAlistamientoLinesFromChecklist(c,changed){
  if(!c || c.currentProcess!=="alistamiento")return {changedLines:0,autoFound:false,message:""};
  c.checklist=c.checklist||{};
  c.orderItems=c.orderItems||[];
  var readyByChecklist=alistamientoChecklistReadyByGeneral(c);
  var cd=cutDoneCount(c);
  var cutsOk=cd.total===0 || cd.done>=cd.total;
  var changedLines=0;
  if(readyByChecklist && c.orderItems.length && cutsOk){
    c.orderItems.forEach(function(it){
      if(it.alistamientoStatus!=="ENCONTRADO" || it.encontrado!==true){
        it.alistamientoStatus="ENCONTRADO";
        it.alistamientoNote=it.alistamientoNote||"Marcado desde checklist operativo unificado.";
        it.alistamientoUpdatedAt=now();
        it.alistamientoUpdatedBy=state.user?state.user.name:"";
        it.estado=it.requiereCorte?"PENDIENTE_CORTE":"ALISTADO";
        it.encontrado=true;
        it.encontradoAt=it.alistamientoUpdatedAt;
        it.encontradoPor=it.alistamientoUpdatedBy;
        it.alistamientoNoveltyReason="";
        it.alistamientoNoveltyDetail="";
        changedLines++;
      }
    });
    c.alistamientoUnifiedSync=c.alistamientoUnifiedSync||[];
    c.alistamientoUnifiedSync.push({at:now(),byName:(state.user&&state.user.name)||"",source:"checklist_general",action:"marcar_todas_las_lineas_encontradas",lines:c.orderItems.length,changedLines:changedLines});
    refreshAlistamientoChecklist(c);
    return {changedLines:changedLines,autoFound:true,message:"Checklist general sincronizó "+c.orderItems.length+" línea(s) como Encontrado."};
  }
  refreshAlistamientoChecklist(c);
  if(readyByChecklist && !cutsOk){
    return {changedLines:0,autoFound:false,message:"Checklist guardado, pero no se marcaron todas las líneas porque hay cortes pendientes "+cd.done+"/"+cd.total+"."};
  }
  return {changedLines:0,autoFound:false,message:"Checklist guardado y sincronizado con el estado actual de las líneas."};
}
function closeChecklist(id){
  var fallback=caseById(id);if(!fallback)return;
  if(!canEditGenericChecklist(fallback)){alert("Este checklist no aplica para este rol o macroproceso.");return;}
  var changed=[], blocked=[], domValues={};
  qsa('.segment[data-id="'+id+'"]').forEach(function(seg){
    var item=seg.getAttribute("data-check"),val=seg.getAttribute("data-current")||"pending",original=seg.getAttribute("data-original")||"pending",reason=checklistManualBlockReason(fallback,item);
    if(val!==original){
      if(reason)blocked.push(item);
      else{domValues[item]=val;changed.push(item+": "+val);}
    }
  });
  if(blocked.length){alert("Algunos puntos no se guardaron porque son automáticos: "+blocked.join(", "));}
  if(!changed.length){alert("No hay cambios nuevos para guardar.");return;}
  if(fallback.currentProcess==="alistamiento"){
    loadFreshCaseForUpdate(id,fallback).then(function(c){
      if(!canEditGenericChecklist(c)){alert("Este checklist no aplica para este rol o macroproceso.");return false;}
      c.checklist=c.checklist||{};
      Object.keys(domValues).forEach(function(k){if(c.checklist[k]!==undefined)c.checklist[k]=domValues[k];});
      var sync=syncAlistamientoLinesFromChecklist(c,changed);
      var ready=alistamientoReadiness(c);
      var detail="Checklist unificado de alistamiento guardado con "+changed.length+" cambio(s). "+changed.join(" · ")+". "+(sync.message||"");
      if(sync.autoFound && ready.ready){detail+=" Pedido listo para enviar a Facturación.";}
      return persistCase(c,{type:"CHECKLIST_CLOSED",detail:detail,visibleRoles:["aux_logistica","coordinador_logistico","lider_logistico","jefe_logistica","facturacion","admin","super_admin","super_administrador"]}).then(function(){
        playNotificationSound("checklistClosed");
        renderDetail(id);
        if(sync.autoFound && ready.ready)alert("Checklist guardado: las líneas quedaron como Encontrado. Ahora puede pulsar Finalizar alistamiento y enviar a facturación.");
        return true;
      });
    }).catch(function(e){showError((e&&e.message)||e||"No fue posible guardar el checklist unificado de alistamiento.");});
    return;
  }
  var c=fallback;
  c.checklist=c.checklist||{};
  Object.keys(domValues).forEach(function(k){if(c.checklist[k]!==undefined)c.checklist[k]=domValues[k];});
  persistCase(c,{type:"CHECKLIST_CLOSED",detail:"Checklist cerrado con "+changed.length+" cambio(s). "+changed.join(" · ")}).then(function(){playNotificationSound("checklistClosed");renderDetail(id);}).catch(function(e){showError(e.message||e);});
}
function discardChecklistChanges(id){
  renderDetail(id);
}
