function excelBar(value,max){var w=max?Math.round((Number(value||0)/max)*100):0;return '<div style="background:#dbeafe;width:160px;height:14px;border:1px solid #bfdbfe"><div style="background:#1d4ed8;width:'+w+'%;height:14px"></div></div>'; }
function excelSectionTable(title,items){
  items=items||[];var max=items.reduce(function(m,x){return Math.max(m,Number(x.value||0));},0)||1;
  return '<h2>'+escapeExcel(title)+'</h2><table border="1" cellspacing="0" cellpadding="4"><tr><th>Concepto</th><th>Cantidad</th><th>Gráfica</th></tr>'+items.map(function(x){return '<tr><td>'+escapeExcel(x.label)+'</td><td>'+Number(x.value||0)+'</td><td>'+excelBar(x.value,max)+'</td></tr>';}).join('')+'</table>';
}
function exportSalesReport(){
  var list=salesReportRows(), summary=salesSummaryStats(list), byAdvisor=salesCountBy(list,salesAdvisorName), byProcess=salesCountBy(list,function(c){return processTitle(c.currentProcess);}), byStatus=salesCountBy(list,function(c){return statusText(c.status);});
  var parts=[], caseRows=[];
  parts.push('<html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif}h1{color:#173b77}h2{color:#173b77;margin-top:24px}table{border-collapse:collapse;margin-bottom:16px}th{background:#173b77;color:#fff}td,th{font-size:12px;border:1px solid #cbd5e1;padding:4px;vertical-align:top}.kpi td{font-size:16px;font-weight:bold;text-align:center}.total-hours{font-weight:bold;background:#eaf2ff}.warn{background:#fff7ed;padding:10px;border:1px solid #fbbf24}</style></head><body>'+ 
    '<h1>Registro de Ventas · '+escapeExcel(isCurrentUserSalesAdvisor()?'mis pedidos':'trazabilidad completa')+'</h1><p>Exportado: '+escapeExcel(new Date().toLocaleString())+'</p><p>El informe respeta los filtros aplicados en el Registro de Ventas. Para asesores solo incluye pedidos creados o asignados a su usuario.</p>');
  function buildMetrics(){
    return excelAsyncAppendRows([],list,'Cálculo registro ventas',function(c){caseRows.push(caseDelayMetrics(c));return '';},10);
  }
  function appendPrincipal(){
    parts.push('<h1>DEMORA EXACTA POR PEDIDO · REGISTRO DE VENTAS</h1><div class="warn"><strong>Tabla principal:</strong> inicio, fin, demora total en horas, esperas, requerimientos y NVA por pedido.</div>'+ 
      '<table border="1" cellspacing="0" cellpadding="4"><thead><tr><th>Pedido</th><th>Orden compra</th><th>Cliente</th><th>Asesor</th><th>Estado cierre</th><th>Proceso actual</th><th>Estado operativo</th><th>Inicio exacto corregido</th><th>Fin exacto / corte análisis</th><th>Tipo de fin</th><th>DEMORA TOTAL HH:MM:SS</th><th>DEMORA TOTAL HORAS</th><th>DEMORA TOTAL DÍAS</th><th>Horas trabajadas VA</th><th>Horas en espera</th><th>Horas en requerimientos</th><th>Horas NVA / sin clasificar</th><th>% VA</th><th>% Espera</th><th>% Requerimientos</th><th>% NVA</th><th>Mayor tipo de demora</th><th>Horas mayor demora</th><th>Proceso con mayor demora</th><th>Horas proceso mayor</th><th>Horas Recepción</th><th>Horas Alistamiento</th><th>Horas Corte</th><th>Horas Facturación</th><th>Horas Caja/Cartera</th><th>Horas Despacho nacional</th><th>Horas Despacho local</th><th>Horas Cliente recoge</th><th>Horas Entrega cliente en punto</th><th>Responsables que intervinieron</th><th>Detalle esperas / requerimientos</th></tr></thead><tbody>');
    return excelAsyncAppendRows(parts,caseRows,'Demora registro ventas',caseDelayPrincipalRow,12);
  }
  function appendSummary(){
    parts.push('</tbody></table><table class="kpi" border="1" cellspacing="0" cellpadding="8"><tr><th>Total pedidos</th><th>Abiertos</th><th>Cerrados</th><th>Requerimientos</th><th>Retenidos</th><th>Parciales</th></tr><tr><td>'+summary.total+'</td><td>'+summary.abiertos+'</td><td>'+summary.cerrados+'</td><td>'+summary.requerimientos+'</td><td>'+summary.retenidos+'</td><td>'+summary.parciales+'</td></tr></table>'+excelSectionTable('Gráfica 1 · Pedidos por asesor',byAdvisor)+excelSectionTable('Gráfica 2 · Distribución por proceso',byProcess)+excelSectionTable('Gráfica 3 · Distribución por estado',byStatus));
  }
  function appendDetail(){
    parts.push('<h2>Base detallada</h2><table border="1" cellspacing="0" cellpadding="4"><thead><tr><th>Pedido</th><th>Orden compra</th><th>Factura</th><th>Cliente</th><th>Asesor</th><th>Proceso actual</th><th>Estado</th><th>Inicio exacto corregido</th><th>Fin exacto / corte</th><th>Demora total HH:MM:SS</th><th>Demora total horas</th><th>Horas espera</th><th>Horas requerimientos</th><th>Entrega solicitada</th><th>Entrega definida</th><th>Responsables que intervinieron</th><th>Flujo con nombres</th><th>Requerimientos</th><th>Anexos</th><th>Notas y comentarios</th><th>Cierre</th></tr></thead><tbody>');
    return excelAsyncAppendRows(parts,list,'Detalle registro ventas',function(c){var m=caseDelayMetrics(c);return '<tr><td>'+escapeExcel(c.reference||'')+'</td><td>'+escapeExcel(purchaseOrderValue(c))+'</td><td>'+escapeExcel(c.invoiceNumber||c.factura||'')+'</td><td>'+escapeExcel(c.client||'')+'</td><td>'+escapeExcel(salesAdvisorName(c))+'</td><td>'+escapeExcel(processTitle(c.currentProcess))+'</td><td>'+escapeExcel(statusText(c.status))+'</td><td>'+escapeExcel(excelDateTime(m.inicio))+'</td><td>'+escapeExcel(excelDateTime(m.fin))+'</td><td>'+escapeExcel(fmt(m.total))+'</td><td>'+m.totalHoras+'</td><td>'+excelHours(m.espera)+'</td><td>'+excelHours(m.req)+'</td><td>'+escapeExcel(c.requestedDelivery?processTitle(c.requestedDelivery):'')+'</td><td>'+escapeExcel(c.deliveryType?processTitle(c.deliveryType):'')+'</td><td>'+escapeExcel(caseResponsibleNames(c))+'</td><td>'+escapeExcel(caseProcessFlowWithNames(c))+'</td><td>'+Number(c.totalRequirements||0)+'</td><td>'+caseAllAttachments(c).length+'</td><td>'+escapeExcel(caseSalesNotesText(c))+'</td><td>'+escapeExcel(c.closedAt?fmtDate(c.closedAt):'')+'</td></tr>';},10);
  }
  return buildMetrics().then(function(){caseRows=caseRows.sort(function(a,b){return Number(b.total||0)-Number(a.total||0);});return appendPrincipal();})
    .then(function(){appendSummary();return appendDetail();})
    .then(function(){parts.push('</tbody></table></body></html>');downloadHtmlExcelParts('registro_ventas_demora_v133_'+new Date().toISOString().slice(0,10)+'.xls',parts);});
}
function resendPendingItems(id){var c=caseById(id);if(!c)return;var pending=(c.orderItems||[]).filter(function(it){return partialQtyParse(it.partialPendingQty)>0 || /PENDIENTE|NO_ENCONTRADO|NOVEDAD|SALDO/i.test(it.estado||it.alistamientoStatus||'');});if(!pending.length){alert('No hay faltantes pendientes para reenviar.');return;}var child=JSON.parse(JSON.stringify(c));var stamp=now(),seq=(c.pendingResends||[]).length+1;child.id=uid('FAL');child.parentCaseId=c.id;child.isPendingResend=true;child.reference=(c.reference||c.id)+'-FALTANTE-'+String(seq).padStart(2,'0');child.currentProcess=isPveOrder(child)?'compras':'recepcion_pedidos';child.status='asignado';ensurePvePurchasingMetadata(child,'Reenvío de faltante V221: PVE pasa primero a Compras');child.assignedRole=primaryOwnerRole(child.currentProcess);child.assignedName=processOwnerTitle(child.currentProcess);child.assignedTo='';child.assignedUid='';child.assignedUsers=[];child.assignedUserIds=[];child.createdAt=stamp;child.updatedAt=stamp;child.closedAt=null;child.openRequirement=null;child.orderItems=pending.map(function(it){var x=Object.assign({},it);x.cantidad=it.partialPendingQty||it.cantidad;x.estado='REENVIADO_FALTANTE';return x;});child.checklist={};(processes[child.currentProcess]||processes.recepcion_pedidos).checklist.forEach(function(x){child.checklist[x]=(x==='Pedido registrado por ventas'||x==='Orden PVE recibida desde ventas')?'ok':'pending';});child.processStats={};procStats(child,'recepcion_pedidos').startedAt=stamp;c.pendingResends=c.pendingResends||[];c.pendingResends.push({id:child.id,at:stamp,byName:state.user.name,items:child.orderItems.length});db.collection('cases').doc(child.id).set(child).then(function(){state.cases.unshift(child);return persistCase(c,{type:'PENDING_ITEMS_RESENT',detail:'Ventas reenvió '+child.orderItems.length+' línea(s) faltante(s) al flujo.',targetRole:'coordinador_logistico',visibleRoles:['ventas','coordinador_logistico','jefe_logistica','admin','super_admin','super_administrador']});}).then(function(){renderSalesReports();}).catch(function(e){showError(e.message||e);});}

