/* ============================================================
   V221_CORTE_MOVIL_REHECHO_FUNCIONAL
   Corte móvil operativo directo.
   Motivo:
   - El flujo móvil estaba fallando incluso con No necesita corte y Medida completa.
   - Se reemplaza la operación móvil por un flujo directo, con escritura real en Firestore.
   - PC conserva su flujo normal.
============================================================ */
function eiV221IsCutUser(){
  return !!(state.user && normalizeRole(state.user.role)==="auxiliar_corte");
}
function eiV221RepairCutUser(){
  // Los permisos provienen únicamente del perfil validado en Firestore.
  return false;
}
function eiV221CanOperateCut(){
  var r=normalizeRole(state.user&&state.user.role);
  return r==="auxiliar_corte" || r==="jefe_logistica" || r==="gerencia" || isAdminRoleValue(r) || currentUserIsSuperAdmin();
}
isCutWorkerUser=function(){return eiV221IsCutUser();};
isCutRuntimeUser=function(){return eiV221IsCutUser();};
canOperateCutModule=function(){return eiV221CanOperateCut();};

function eiV221Clone(o){try{return JSON.parse(JSON.stringify(o||{}));}catch(e){return Object.assign({},o||{});}}
function eiV221ReplaceCase(c){
  if(!c||!c.id)return;
  state.cases=state.cases||[];
  var found=false;
  for(var i=0;i<state.cases.length;i++){
    if(state.cases[i]&&state.cases[i].id===c.id){state.cases[i]=c;found=true;break;}
  }
  if(!found)state.cases.unshift(c);
}
function eiV221ReadFormIntoCut(cut){
  try{if(qs("#cutFullForm"))applyCutFormValues(cut);}catch(e){novaCaptureError(e,"operación heredada");}
  cut.tipoPedido=cut.tipoPedido||"VENTAS";
  cut.siesaBodega=cut.siesaBodega||((window.appSettings&&window.appSettings.siesaFlatFile&&window.appSettings.siesaFlatFile.warehouse)||"PENDIENTE_VALIDAR");
  if(cut.corteUniforme===undefined)cut.corteUniforme=true;
  if(cut.tramoRotulado===undefined)cut.tramoRotulado=true;
  if(cut.evidenciaRegistro===undefined)cut.evidenciaRegistro=true;
}
function eiV221PrepareCaseCut(c,cut){
  if(!c||!cut)return;
  eiV221RepairCutUser();
  c.hasCuts=true;
  c.visibleRoles=Array.isArray(c.visibleRoles)?c.visibleRoles:[];
  ["auxiliar_corte","auxiliar_de_corte","operario_corte","operario_de_corte","corte","cortes","jefe_logistica","admin","super_admin","coordinador_logistico","lider_logistico","aux_logistica"].forEach(function(r){
    if(c.visibleRoles.indexOf(r)<0)c.visibleRoles.push(r);
  });
  cut.id=cut.id||uid("CUT");
  cut.caseId=c.id;
  cut.pedido=cut.pedido||c.reference||"";
  cut.cliente=cut.cliente||c.client||"";
  cut.code=cut.code||("CT-"+(((c.cutRequests||[]).indexOf(cut)+1)||1));
  cut.status=cut.status||"PENDIENTE_CORTE";
  cut.takenByUid=cut.takenByUid||state.user.uid;
  cut.takenByName=cut.takenByName||state.user.name;
  cut.takenAt=cut.takenAt||now();
  eiV221ReadFormIntoCut(cut);
}
function eiV221PersistCutCase(c,cut,event,expected){
  if(!db||!c||!c.id){
    alert("No hay conexión a Firestore. No se puede guardar el corte.");
    return Promise.reject(new Error("Sin Firestore."));
  }
  c.updatedAt=now();
  c.updatedBy=state.user&&state.user.uid;
  c.updatedByName=state.user&&state.user.name;
  c.lastMobileCutWriteVersion="V221";
  c.lastMobileCutWriteAt=now();
  if(cut){
    cut.lastMobileCutWriteVersion="V221";
    cut.lastMobileCutWriteAt=now();
  }
  event=event||{};
  event=Object.assign({caseId:c.id,process:c.currentProcess,timestamp:now(),visibleRoles:["auxiliar_corte","aux_logistica","coordinador_logistico","lider_logistico","jefe_logistica","admin","super_admin"]},event);
  try{appendFlowTraceFromEvent(c,event);}catch(e){novaCaptureError(e,"operación heredada");}
  return db.collection("cases").doc(c.id).set(c,{merge:true}).then(function(){
    return db.collection("cases").doc(c.id).get();
  }).then(function(doc){
    if(!doc||!doc.exists)throw new Error("Firestore no devolvió el caso guardado.");
    var remote=doc.data()||{};remote.id=doc.id;
    var remoteCut=(remote.cutRequests||[]).find(function(x){return x&&cut&&x.id===cut.id;});
    if(expected&&expected.cutStatus && (!remoteCut || remoteCut.status!==expected.cutStatus)){
      throw new Error("El corte no quedó en estado "+expected.cutStatus+" en Firestore.");
    }
    if(expected&&expected.currentProcess && remote.currentProcess!==expected.currentProcess){
      throw new Error("El pedido no quedó en "+expected.currentProcess+" en Firestore.");
    }
    eiV221ReplaceCase(remote);
    return createEvent(enrichCaseEvent(remote,event)).catch(function(e){console.warn("[V221] Caso guardado; evento no creado",e);}).then(function(){return remote;});
  }).catch(function(e){
    var msg=(e&&e.message)||String(e||"");
    var authEmail="",authUid="";
    try{
      authEmail=String((auth&&auth.currentUser&&auth.currentUser.email)||"");
      authUid=String((auth&&auth.currentUser&&auth.currentUser.uid)||"");
    }catch(x){novaCaptureError(x,"operación heredada");}
    alert(
      "Firestore rechazó la actualización real del corte. " +
      "Firestore sigue rechazando la escritura. Verifique en consola el projectId mostrado por [V221 Firebase] y publique allí firestore.rules V221.\n\n" +
      "Usuario autenticado: "+(authEmail||"sin correo")+"\nUID: "+(authUid||"sin UID")+"\n\n" +
      "Detalle: "+msg
    );
    try{console.error("[V221 corte móvil · permiso Firestore]",e,{authEmail:authEmail,authUid:authUid,caseId:c&&c.id,cutId:cut&&cut.id,event:event,expected:expected});}catch(x){novaCaptureError(x,"operación heredada");}
    throw e;
  });
}
function eiV221ValidateNumbers(cut,needFinal){
  var total=cutParseDecimal(cut.disponibleAntes);
  var sol=cutParseDecimal(cut.metrosSolicitados||cut.metrajeFinal);
  if(!Number.isFinite(total)||total<=0){alert("Ingrese el tamaño total del carreto / chipa.");return false;}
  if(Number.isFinite(sol)&&total<sol){alert("El tamaño total del carreto no puede ser menor a los metros a cortar.");return false;}
  if(needFinal){
    var fin=cutParseDecimal(cut.metrajeFinal||cut.metrosSolicitados);
    if(!Number.isFinite(fin)||fin<=0){alert("Ingrese el metraje final / metros cortados.");return false;}
  }
  return true;
}
function eiV221SendCutToAlistamiento(c,cut,mode){
  syncCutSourceLineToAlistamiento(c,cut,mode||"CORTE_REGISTRADO");
  var pending=(c.cutRequests||[]).filter(function(x){return !cutIsOperationallyDone(x)&&x.id!==cut.id;});
  c.cutReturnAlerts=c.cutReturnAlerts||[];
  c.cutReturnAlerts.push({
    id:uid("CRA"),
    cutId:cut.id,
    cutCode:cut.code||cut.id,
    reference:cut.referencia||cut.descripcion||"Corte",
    meters:cutNormalizeDecimal(cut.metrajeFinal||cut.metrosSolicitados||""),
    returnedAt:now(),
    returnedBy:state.user.name,
    status:"DISPONIBLE_PARA_EMPALETAR",
    detail:"Recoger en corte, llevar a alistamiento y empaletar para facturación."
  });
  if(c.cutReturnAlerts.length>25)c.cutReturnAlerts=c.cutReturnAlerts.slice(-25);
  stopWait(c);
  stopActive(c);
  procStats(c,"corte_cable").completedAt=pending.length===0?(procStats(c,"corte_cable").completedAt||now()):procStats(c,"corte_cable").completedAt;
  c.currentProcess="alistamiento";
  c.status="en_proceso";
  c.assignedRole=primaryOwnerRole("alistamiento");
  c.assignedName=processOwnerTitle("alistamiento");
  releaseCaseFromCutOwner(c);
  c.assignedTo="";
  c.deadStartedAt=now();
  c.activeStartedAt=now();
  c.waitStartedAt=null;
  c.checklist=c.checklist||{};
  processes.alistamiento.checklist.forEach(function(x){if(c.checklist[x]===undefined)c.checklist[x]="pending";});
  if(c.checklist["Cortes terminados o en seguimiento"]!==undefined)c.checklist["Cortes terminados o en seguimiento"]=pending.length===0?"ok":"pending";
  if(c.checklist["Pedido listo para facturación"]!==undefined)c.checklist["Pedido listo para facturación"]="pending";
  return pending;
}
